-- Source: database/functions/occasion_setup/drafts.sql
-- Drafts are private workspace objects, never public occasions.
CREATE TABLE IF NOT EXISTS public.occasion_setup_drafts (
  id uuid PRIMARY KEY,
  unit bigint NOT NULL REFERENCES public.units(id) ON DELETE CASCADE,
  organization bigint NOT NULL REFERENCES public.organizations(id),
  author uuid NOT NULL REFERENCES auth.users(id),
  data jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(data) = 'object' AND octet_length(data::text) <= 262144),
  revision bigint NOT NULL DEFAULT 1,
  current_step integer NOT NULL DEFAULT 0 CHECK (current_step BETWEEN 0 AND 6),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.occasion_setup_drafts DROP CONSTRAINT IF EXISTS occasion_setup_drafts_current_step_check;
ALTER TABLE public.occasion_setup_drafts ADD CONSTRAINT occasion_setup_drafts_current_step_check CHECK (current_step BETWEEN 0 AND 6);
CREATE INDEX IF NOT EXISTS occasion_setup_drafts_unit_idx ON public.occasion_setup_drafts(unit);
ALTER TABLE public.occasion_setup_drafts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.occasion_setup_drafts FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.get_occasion_setup_drafts(p_unit bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT (public.get_is_editor_on_unit(p_unit) OR public.get_is_manager_on_unit(p_unit)) THEN
    RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501';
  END IF;
  RETURN COALESCE((SELECT jsonb_agg(to_jsonb(d) ORDER BY updated_at DESC)
    FROM public.occasion_setup_drafts d WHERE unit = p_unit), '[]'::jsonb);
END $$;

-- Run the canonical creator inside a rollback-only subtransaction. Its
-- complete configuration survives in a PL/pgSQL variable, but no occasion,
-- form, product, reminders or other rows escape into the normal application.
-- PostgreSQL sequences may advance; those IDs are draft-local references.
CREATE OR REPLACE FUNCTION public.build_occasion_setup_configuration(p_unit bigint, p_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE configuration jsonb; organization_id bigint;
  provisional_link text := 'draft-' || p_id::text;
BEGIN
  IF auth.uid() IS NULL OR NOT (public.get_is_editor_on_unit(p_unit) OR public.get_is_manager_on_unit(p_unit)) THEN
    RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501';
  END IF;
  SELECT organization INTO organization_id FROM public.units WHERE id = p_unit;
  BEGIN
    PERFORM public.update_occasion_internal_v1(jsonb_build_object(
      'unit',p_unit,'organization',organization_id,'title','',
      'link',provisional_link,'is_hidden',true,'is_open',false,
      'start_time',now()+interval '30 days','end_time',now()+interval '33 days'));
    SELECT item INTO configuration
      FROM jsonb_array_elements(public.get_occasion_setup_sources(p_unit)) item
      WHERE item->'occasion'->>'link' = provisional_link;
    IF configuration IS NULL THEN RAISE EXCEPTION 'Creation configuration missing'; END IF;
    RAISE EXCEPTION 'Rollback provisional creation' USING ERRCODE = 'ZX001';
  EXCEPTION WHEN SQLSTATE 'ZX001' THEN
    -- Variables retain their values while all writes in the block roll back.
    NULL;
  END;
  configuration := jsonb_set(configuration,'{occasion,link}','""'::jsonb);
  configuration := jsonb_set(configuration,'{forms}',coalesce((SELECT jsonb_agg(jsonb_set(f,'{link}','""'::jsonb))
    FROM jsonb_array_elements(configuration->'forms') f),'[]'::jsonb));
  RETURN configuration;
END $$;
REVOKE ALL ON FUNCTION public.build_occasion_setup_configuration(bigint,uuid) FROM PUBLIC,anon,authenticated;

-- Client-generated UUID makes canonical draft initialization safe to retry.
CREATE OR REPLACE FUNCTION public.create_occasion_setup_draft(p_id uuid, p_unit bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE d public.occasion_setup_drafts; configuration jsonb; is_new boolean; policy jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT (public.get_is_editor_on_unit(p_unit) OR public.get_is_manager_on_unit(p_unit)) THEN
    RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501';
  END IF;
  -- Serialize identical UUIDs before inspecting existence, without charging retries.
  PERFORM pg_advisory_xact_lock(hashtextextended('draft:'||p_id::text,0));
  is_new:=NOT EXISTS(SELECT 1 FROM public.occasion_setup_drafts WHERE id=p_id);
  IF is_new THEN
    policy:=public.abuse_effective_rules_v1('occasion.draft',p_unit,(SELECT organization FROM public.units WHERE id=p_unit));
    PERFORM public.admit_occasion_draft_v1(auth.uid(),p_unit,
      (SELECT organization FROM public.units WHERE id=p_unit),0,true,true,policy);
  END IF;
  INSERT INTO public.occasion_setup_drafts(id,unit,organization,author)
    SELECT p_id,id,organization,auth.uid() FROM public.units WHERE id = p_unit
    ON CONFLICT (id) DO NOTHING;
  SELECT * INTO d FROM public.occasion_setup_drafts WHERE id = p_id FOR UPDATE;
  IF d.unit IS DISTINCT FROM p_unit OR d.author IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501';
  END IF;
  IF NOT (d.data ? 'defaultConfiguration') THEN
    IF NOT is_new THEN
      policy:=public.abuse_effective_rules_v1('occasion.draft',p_unit,d.organization);
      PERFORM public.admit_occasion_draft_v1(auth.uid(),p_unit,d.organization,0,false,true,policy);
    END IF;
    configuration := public.build_occasion_setup_configuration(p_unit,p_id);
    UPDATE public.occasion_setup_drafts SET data =
      jsonb_build_object('defaultConfiguration',configuration,
        'formDraft',configuration->'forms'->0,'formDefaultsFollowEvent',true)
      || d.data WHERE id = p_id RETURNING * INTO d;
    PERFORM public.admit_occasion_draft_v1(auth.uid(),p_unit,d.organization,octet_length(d.data::text),false,false,policy);
  END IF;
  RETURN to_jsonb(d);
END $$;

CREATE OR REPLACE FUNCTION public.initialize_occasion_setup_draft_defaults(p_id uuid, p_expected_revision bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE d public.occasion_setup_drafts; configuration jsonb; policy jsonb;
BEGIN
  SELECT * INTO d FROM public.occasion_setup_drafts WHERE id = p_id FOR UPDATE;
  IF NOT FOUND OR auth.uid() IS NULL OR NOT (public.get_is_editor_on_unit(d.unit) OR public.get_is_manager_on_unit(d.unit)) THEN
    RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501';
  END IF;
  IF d.data ? 'defaultConfiguration' THEN RETURN to_jsonb(d); END IF;
  IF d.revision IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'Draft changed in another session' USING ERRCODE = '40001';
  END IF;
  policy:=public.abuse_effective_rules_v1('occasion.draft',d.unit,d.organization);
  PERFORM public.admit_occasion_draft_v1(auth.uid(),d.unit,d.organization,0,false,true,policy);
  configuration := public.build_occasion_setup_configuration(d.unit,p_id);
  UPDATE public.occasion_setup_drafts SET data =
    jsonb_build_object('defaultConfiguration',configuration,
      'formDraft',configuration->'forms'->0,'formDefaultsFollowEvent',true)
    || d.data, revision = revision+1, updated_at=now()
    WHERE id=p_id RETURNING * INTO d;
  PERFORM public.admit_occasion_draft_v1(auth.uid(),d.unit,d.organization,octet_length(d.data::text),false,false,policy);
  RETURN to_jsonb(d);
END $$;
REVOKE ALL ON FUNCTION public.initialize_occasion_setup_draft_defaults(uuid,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.initialize_occasion_setup_draft_defaults(uuid,bigint) TO authenticated;

CREATE OR REPLACE FUNCTION public.save_occasion_setup_draft(p_id uuid, p_expected_revision bigint, p_data jsonb, p_step integer)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE d public.occasion_setup_drafts;
BEGIN
  SELECT * INTO d FROM public.occasion_setup_drafts WHERE id = p_id FOR UPDATE;
  IF NOT FOUND OR auth.uid() IS NULL OR NOT (public.get_is_editor_on_unit(d.unit) OR public.get_is_manager_on_unit(d.unit)) THEN
    RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501';
  END IF;
  IF d.data ? 'finalizedOccasion' THEN RAISE invalid_parameter_value USING MESSAGE='Draft already finalized'; END IF;
  p_data := p_data - 'finalizedOccasion' - 'finalizeResponse';
  IF p_data IS NULL OR jsonb_typeof(p_data) <> 'object' OR octet_length(p_data::text) > 262144 OR p_step IS NULL OR p_step NOT BETWEEN 0 AND 6 THEN
    RAISE EXCEPTION 'Invalid draft' USING ERRCODE = '22023'; END IF;
  IF d.data ? 'copy_locale' THEN p_data := jsonb_set(p_data,'{copy_locale}',d.data->'copy_locale'); END IF;
  IF p_data ? 'copy_locale' AND p_data->>'sourceId' IS NOT NULL
     AND coalesce((p_data->>'copy_title_edited')::boolean,false)=false AND coalesce(p_data->>'title','')='' THEN
    IF NOT public.can_copy_occasion_source((p_data->>'sourceId')::bigint) OR NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=(p_data->>'sourceId')::bigint AND organization=d.organization) THEN
      RAISE insufficient_privilege USING MESSAGE='Copy source denied'; END IF;
    IF d.revision=p_expected_revision+1 AND d.data->>'sourceId'=p_data->>'sourceId' THEN
      p_data := jsonb_set(p_data,'{title}',d.data->'title');
    ELSE
      p_data := jsonb_set(p_data,'{title}',to_jsonb(public.copy_occasion_title_internal(
        (SELECT title FROM public.occasions WHERE id=(p_data->>'sourceId')::bigint),p_data->>'copy_locale')));
    END IF;
  END IF;
  IF d.revision = p_expected_revision + 1 AND d.data = p_data AND d.current_step = p_step THEN RETURN to_jsonb(d); END IF;
  IF d.revision IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'Draft changed in another session' USING ERRCODE = '40001'; END IF;
  PERFORM public.admit_occasion_draft_v1(auth.uid(),d.unit,d.organization,octet_length(p_data::text),false,false);
  UPDATE public.occasion_setup_drafts SET data = p_data, current_step = p_step,
    revision = revision + 1, updated_at = now() WHERE id = p_id RETURNING * INTO d;
  RETURN to_jsonb(d);
END $$;

CREATE OR REPLACE FUNCTION public.delete_occasion_setup_draft(p_id uuid, p_unit bigint, p_expected_revision bigint)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE d public.occasion_setup_drafts;
BEGIN
  IF auth.uid() IS NULL OR NOT (public.get_is_editor_on_unit(p_unit) OR public.get_is_manager_on_unit(p_unit)) THEN
    RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO d FROM public.occasion_setup_drafts WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  IF d.unit <> p_unit THEN RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501'; END IF;
  IF d.revision IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'Draft changed in another session' USING ERRCODE = '40001';
  END IF;
  DELETE FROM public.occasion_setup_drafts WHERE id = p_id;
END $$;

REVOKE ALL ON FUNCTION public.get_occasion_setup_drafts(bigint), public.create_occasion_setup_draft(uuid,bigint),
  public.save_occasion_setup_draft(uuid,bigint,jsonb,integer), public.delete_occasion_setup_draft(uuid,bigint,bigint) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_occasion_setup_drafts(bigint), public.create_occasion_setup_draft(uuid,bigint),
  public.save_occasion_setup_draft(uuid,bigint,jsonb,integer), public.delete_occasion_setup_draft(uuid,bigint,bigint) TO authenticated;


-- Source: database/functions/occasion_setup/finalize.sql
-- Materialize the private configuration exactly once. Provisional draft IDs and
-- source product IDs are never accepted as IDs in the new aggregate.
CREATE OR REPLACE FUNCTION public.finalize_occasion_setup_draft(p_id uuid,p_expected_revision bigint,p_command_id uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE policies jsonb; d public.occasion_setup_drafts; payload jsonb; config jsonb; features jsonb := '[]';
 started jsonb; receipt jsonb; new_id bigint; form_id bigint; form_data jsonb; fields jsonb := '[]';
 field jsonb; pt jsonb; products jsonb; product jsonb; result jsonb; source_id bigint;
 old_products jsonb := '[]'; old_types jsonb := '[]'; type_map jsonb := '{}'; final_features jsonb; new_products jsonb; product_map jsonb := '{}'; idx integer; j integer;
 blueprint_id bigint; objects jsonb := '[]'; obj jsonb; v_commit public.client_commits%ROWTYPE;
BEGIN
 SELECT * INTO d FROM public.occasion_setup_drafts WHERE id=p_id FOR UPDATE;
 IF NOT FOUND OR auth.uid() IS NULL OR NOT (public.get_is_editor_on_unit(d.unit) OR public.get_is_manager_on_unit(d.unit)) THEN
  RAISE insufficient_privilege USING MESSAGE='Draft access denied'; END IF;
 IF d.data ? 'finalizeResponse' THEN RETURN d.data->'finalizeResponse'; END IF;
 started := public.begin_unit_client_mutation_v1(p_command_id,'occasion.setup.finalize',d.unit,auth.uid(),
  encode(extensions.digest(convert_to(jsonb_build_object('draft',p_id,'revision',p_expected_revision)::text,'UTF8'),'sha256'),'hex'));
 IF started->>'disposition'='replay' THEN RETURN started->'response'; END IF;
 IF d.data ? 'finalizedOccasion' THEN RAISE invalid_parameter_value USING MESSAGE='Draft already finalized'; END IF;
 IF d.revision IS DISTINCT FROM p_expected_revision THEN RAISE serialization_failure USING MESSAGE='Draft changed in another session'; END IF;
 payload := d.data;
 source_id := (payload->>'sourceId')::bigint;
 IF source_id IS NOT NULL AND (NOT public.can_copy_occasion_source(source_id) OR NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=source_id AND organization=d.organization)) THEN
  RAISE insufficient_privilege USING MESSAGE='Copy source denied'; END IF;
 IF nullif(btrim(payload->>'title'),'') IS NULL OR (payload->>'reviewConfirmed')::boolean IS DISTINCT FROM true THEN
  RAISE invalid_parameter_value USING MESSAGE='Draft review required'; END IF;
 IF (payload->>'end')::timestamptz < (payload->>'start')::timestamptz THEN
  RAISE invalid_parameter_value USING MESSAGE='Invalid event dates'; END IF;
 IF payload->'ticketDraft' IS NOT NULL AND payload->'ticketDraft'<>'null'::jsonb THEN features := features || jsonb_build_array((payload->'ticketDraft')-'layout'); END IF;
 IF coalesce((payload->>'formEnabled')::boolean,true) THEN features := features || '[{"code":"form","is_enabled":true}]'; END IF;
 IF coalesce((payload->>'copyProgram')::boolean,false) THEN features := features || '[{"code":"schedule","is_enabled":true}]'; END IF;
 IF coalesce((payload->>'copyInformation')::boolean,false) THEN features := features || '[{"code":"information","is_enabled":true}]'; END IF;
 config := jsonb_build_object('unit',d.unit,'organization',d.organization,
  'title',payload->>'title','link',payload->>'link','description',coalesce(payload->>'description',''),
  'start_time',payload->>'start','end_time',payload->>'end','is_hidden',true,'is_open',false,
  'features',features,'data',jsonb_build_object('client_sync_v1',false));
 policies:=public.abuse_policy_bundle_v1(ARRAY['occasion.creation','occasion.copy'],d.unit,d.organization);
 IF source_id IS NOT NULL AND (coalesce((payload->>'copyProgram')::boolean,false) OR coalesce((payload->>'copyInformation')::boolean,false) OR coalesce((payload->>'copyEmails')::boolean,false)) THEN
  PERFORM public.admit_occasion_copy_v1(source_id,d.unit,d.organization,policies->'occasion.copy'); END IF;
 PERFORM public.admit_occasion_creation_v1(auth.uid(),d.unit,d.organization,NULL,policies->'occasion.creation');
 PERFORM public.update_occasion_internal_v1(config);
 new_id := currval(pg_get_serial_sequence('public.occasions','id'));
 SELECT o.features INTO features FROM public.occasions o WHERE o.id=new_id;
 INSERT INTO public.occasion_users(occasion,"user",is_manager,is_editor,is_editor_view,is_editor_order,is_editor_order_view)
 VALUES(new_id,auth.uid(),true,true,true,true,true);
 form_data := payload->'formDraft';
 IF form_data IS NOT NULL AND form_data<>'null'::jsonb AND coalesce((payload->>'formEnabled')::boolean,true) THEN
  SELECT id INTO form_id FROM public.forms WHERE occasion=new_id ORDER BY id LIMIT 1;
  IF form_id IS NULL THEN
   result := public.create_form_internal_v1(new_id,NULL,form_data->>'title'); form_id := (result->>'id')::bigint;
  END IF;
  DELETE FROM public.form_fields WHERE form=form_id;
  DELETE FROM eshop.products WHERE occasion=new_id;
  DELETE FROM eshop.product_types WHERE occasion=new_id;
  -- Every field/product is newly owned by this occasion. Retain a local mapping
  -- for seats that referred to draft/source product IDs.
  FOR field IN SELECT value FROM jsonb_array_elements(coalesce(form_data->'fields','[]')) LOOP
   pt := coalesce(nullif(field->'product_type_data','null'::jsonb),field->'product_type');
   IF jsonb_typeof(pt)<>'object' THEN pt := NULL; END IF;
   field := field - 'id' - 'form' - 'product_type';
   IF pt IS NOT NULL AND pt<>'null'::jsonb THEN
    old_products := old_products || coalesce(pt->'products','[]');
    products := '[]';
    FOR product IN SELECT value FROM jsonb_array_elements(coalesce(pt->'products','[]')) LOOP
     products := products || jsonb_build_array(product-'id'-'occasion'-'product_type');
    END LOOP;
    field := (field-'product_type_data') || jsonb_build_object('product_type',(pt-'id'-'occasion') || jsonb_build_object('products',products));
   END IF;
   old_types := old_types || jsonb_build_array(pt->'id');
   fields := fields || jsonb_build_array(field);
  END LOOP;
  result := public.update_form_internal_v1((form_data-'id'-'fields'-'blueprint'-'bank_account') || jsonb_build_object(
   'id',form_id,'occasion',new_id,'link',coalesce(nullif(form_data->>'link',''),(SELECT link FROM public.forms WHERE id=form_id)),
   'is_open',false,'form_fields',fields));
  IF result->>'code'<>'200' THEN RAISE EXCEPTION '%',result; END IF;
  IF jsonb_array_length(old_types)>0 THEN
   FOR idx IN 0..jsonb_array_length(old_types)-1 LOOP
    IF old_types->>idx IS NOT NULL THEN type_map := type_map || jsonb_build_object(old_types->>idx,result->'form_fields'->idx->'product_type'->'id'); END IF;
   END LOOP;
  END IF;
  SELECT coalesce(jsonb_agg(p ORDER BY field_order,product_order),'[]') INTO new_products
  FROM (SELECT p,ff.ordinality field_order,pp.ordinality product_order
   FROM jsonb_array_elements(result->'form_fields') WITH ORDINALITY ff(f,ordinality)
   CROSS JOIN LATERAL jsonb_array_elements(coalesce(ff.f->'product_type'->'products','[]')) WITH ORDINALITY pp(p,ordinality)) x;
  IF jsonb_array_length(old_products)>0 THEN
   FOR idx IN 0..jsonb_array_length(old_products)-1 LOOP
    IF old_products->idx->>'id' IS NOT NULL THEN product_map := product_map || jsonb_build_object(old_products->idx->>'id',new_products->idx->'id'); END IF;
   END LOOP;
  END IF;
  IF jsonb_array_length(coalesce(payload->'blueprintObjects','[]'))>0 THEN
   FOR obj IN SELECT value FROM jsonb_array_elements(payload->'blueprintObjects') LOOP
    obj := obj-'id'-'order_product_ticket'-'secret';
    IF obj->>'product' IS NOT NULL THEN obj := jsonb_set(obj,'{product}',coalesce(product_map->(obj->>'product'),'null'::jsonb)); END IF;
    objects := objects || jsonb_build_array(obj);
   END LOOP;
   result := public.update_blueprint_internal_v1(jsonb_build_object('occasion',new_id,'organization',d.organization,
    'title',payload->>'blueprintTitle','configuration',jsonb_build_object('dimensions',jsonb_build_object(
     'width',coalesce((payload->>'blueprintWidth')::numeric,12),'height',coalesce((payload->>'blueprintHeight')::numeric,8))),
    'groups',coalesce(payload->'blueprintGroups','[]'),'objects',objects,'background_svg',payload->>'blueprintBackground'));
   IF (result->>'code')::int NOT IN (200,201) THEN RAISE EXCEPTION '%',result; END IF;
   blueprint_id := (result->>'blueprint_id')::bigint;
   UPDATE public.forms SET blueprint=blueprint_id WHERE id=form_id;
   features := features || '[{"code":"blueprint","is_enabled":true}]';
  END IF;
 END IF;
 -- Rebind ticket product-type references only after their new IDs exist.
 IF payload->'ticketDraft' ? 'layout' THEN
  pt := payload->'ticketDraft';
  SELECT jsonb_set(pt,'{layout,templates}',jsonb_object_agg(t.key,
    jsonb_set(t.value,'{elements}',coalesce((SELECT jsonb_agg(CASE WHEN e->>'binding'='productType'
      THEN jsonb_set(e,'{productTypeId}',coalesce(type_map->(e->>'productTypeId'),'null'::jsonb)) ELSE e END ORDER BY n)
      FROM jsonb_array_elements(t.value->'elements') WITH ORDINALITY x(e,n)),'[]'::jsonb))))
   INTO pt FROM jsonb_each(pt->'layout'->'templates') t;
  features := (SELECT jsonb_agg(CASE WHEN f->>'code'='ticket' THEN pt ELSE f END) FROM jsonb_array_elements(features) f);
 END IF;
 PERFORM public.validate_ticket_layout_references(new_id,f->'layout') FROM jsonb_array_elements(features) f WHERE f ? 'layout';
 final_features := features;
 UPDATE public.occasions SET features=final_features WHERE id=new_id;
 IF coalesce((payload->>'copyProgram')::boolean,false) THEN
  INSERT INTO public.events(occasion,title,start_time,end_time,description)
  SELECT new_id,e->>'title',(e->>'start_time')::timestamptz,(e->>'end_time')::timestamptz,e->>'description'
  FROM jsonb_array_elements(coalesce(payload->'sourceProgram','[]')) e;
 END IF;
 IF coalesce((payload->>'copyInformation')::boolean,false) THEN
  INSERT INTO public.information(occasion,unit,title,description,type,data)
  SELECT new_id,d.unit,i->>'title',i->>'description',i->>'type',i->'data'
  FROM jsonb_array_elements(coalesce(payload->'sourceInformation','[]')) i;
 END IF;
 IF coalesce((payload->>'copyEmails')::boolean,false) AND source_id IS NOT NULL THEN
  INSERT INTO public.email_templates(occasion,unit,organization,code,title,subject,html)
  SELECT new_id,d.unit,d.organization,code,title,subject,html FROM public.email_templates WHERE occasion=source_id;
 END IF;
 PERFORM public.admit_occasion_copy_v1(new_id,d.unit,d.organization,policies->'occasion.copy');
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 VALUES('occasion','occasion',new_id,new_id::text,1);
 INSERT INTO public.client_commits(unit,actor_id,actor_kind,source,change_class)
 VALUES(d.unit,auth.uid(),'user','occasion.setup.finalize','configuration') RETURNING * INTO v_commit;
 INSERT INTO public.client_commit_items(commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
 SELECT v_commit.commit_id,0,'occasion',new_id::text,'insert',left(title,240),ARRAY['aggregate'] FROM public.occasions WHERE id=new_id;
 PERFORM public.fanout_unit_catalog_v1(v_commit.commit_id,d.unit);
 receipt := jsonb_build_object('status','applied','code',200,'data',
  jsonb_build_object('occasionId',new_id,'link',(SELECT link FROM public.occasions WHERE id=new_id)));
 receipt := public.finish_client_mutation_v1(p_command_id,receipt,v_commit.commit_id);
 UPDATE public.occasion_setup_drafts SET data=data || jsonb_build_object('finalizedOccasion',new_id,'finalizeResponse',receipt),revision=revision+1 WHERE id=p_id;
 RETURN receipt;
END $$;
REVOKE ALL ON FUNCTION public.finalize_occasion_setup_draft(uuid,bigint,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.finalize_occasion_setup_draft(uuid,bigint,uuid) TO authenticated;


-- Source: database/functions/units/create_unit_and_assign_manager.sql
CREATE OR REPLACE FUNCTION create_unit_and_assign_manager(
  title text
) RETURNS jsonb
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_user_id uuid;
  v_org_id bigint;
  v_email text;
  v_new_unit_id bigint;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('code', 401, 'message', 'Unauthorized');
  END IF;

  SELECT organization, email_readonly 
  INTO v_org_id, v_email
  FROM public.user_info 
  WHERE id = v_user_id;

  IF v_org_id IS NULL THEN
     RETURN jsonb_build_object('code', 404, 'message', 'User info or organization not found');
  END IF;

  -- Check if unit creation is enabled for organization
  DECLARE
      v_is_enabled boolean;
  BEGIN
      SELECT (data->>'IS_UNIT_CREATION_ENABLED')::boolean 
      INTO v_is_enabled
      FROM public.organizations 
      WHERE id = v_org_id;
      
      IF v_is_enabled IS NOT TRUE THEN
          RETURN jsonb_build_object('code', 403, 'message', 'Unit creation is disabled for this organization');
      END IF;
  END;

  PERFORM public.admit_unit_creation_v1(v_user_id,v_org_id);

  INSERT INTO public.units (title, organization, data)
  VALUES (
    title, 
    v_org_id,
    jsonb_build_object(
        'reply_to', lower(trim(COALESCE(v_email, ''))),
        'timezone', 'Europe/Prague'
    )
  )
  RETURNING id INTO v_new_unit_id;

  INSERT INTO public.unit_users (unit, "user", is_manager, is_editor, is_editor_view)
  VALUES (v_new_unit_id, v_user_id, true, true, true);

  RETURN jsonb_build_object(
    'code', 200, 
    'message', 'Unit created successfully', 
    'data', jsonb_build_object('id', v_new_unit_id)
  );

EXCEPTION WHEN SQLSTATE 'PT429' THEN
  RETURN jsonb_build_object('code',429,'message','Capacity is temporarily limited. Try again later.');
WHEN OTHERS THEN
  RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$$ LANGUAGE plpgsql;
REVOKE ALL ON FUNCTION public.create_unit_and_assign_manager(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_unit_and_assign_manager(text) TO authenticated;


-- Source: database/functions/users/initialize_registration_unit_v1.sql
-- Internal initializer shared by password and externally verified registration.
CREATE OR REPLACE FUNCTION public.initialize_registration_unit_v1(p_user uuid,p_organization bigint,p_raw_email text,p_title text)
RETURNS bigint LANGUAGE plpgsql SET search_path=public,extensions AS $$
DECLARE v_unit bigint;
BEGIN
  PERFORM public.admit_unit_creation_v1(p_user,p_organization);
  INSERT INTO public.units(title,organization,data) VALUES(p_title,p_organization,jsonb_build_object('reply_to',lower(btrim(p_raw_email)),'timezone','Europe/Prague')) RETURNING id INTO v_unit;
  INSERT INTO public.unit_users(unit,"user",is_manager,is_editor,is_editor_view) VALUES(v_unit,p_user,true,true,true);
  RETURN v_unit;
END $$;
REVOKE ALL ON FUNCTION public.initialize_registration_unit_v1(uuid,bigint,text,text) FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/abuse/email.sql
CREATE OR REPLACE FUNCTION public.abuse_recipient_key_v1(p_recipient text) RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT encode(extensions.hmac(lower(btrim(p_recipient)),encode(secret,'hex'),'sha256'),'hex')
 FROM public.abuse_identity_key WHERE singleton;
$$;
REVOKE ALL ON FUNCTION public.abuse_recipient_key_v1(text) FROM PUBLIC,anon,authenticated,service_role;

-- Shared classification also adopts pending pre-cutover intents without recharging them.
CREATE OR REPLACE FUNCTION public.email_admission_class_v1(m public.email_messages) RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE o eshop.orders; commitment boolean:=false;
BEGIN
 IF m.message_kind IN ('order_tickets','order_payment_notice','order_storno') AND m.order_id IS NOT NULL THEN
  SELECT * INTO o FROM eshop.orders WHERE id=m.order_id;
  commitment:=((m.message_kind IN ('order_tickets','order_payment_notice') AND o.state IN ('paid','sent')) OR (m.message_kind='order_storno' AND o.state='storno')) AND o.occasion=m.occasion AND o.email_payment_version=m.source_version
   AND m.recipient IS NOT DISTINCT FROM o.data->>'email'
   AND m.dedupe_key=o.id||':'||o.email_payment_version||':'||coalesce(m.recipient,'')||CASE WHEN m.message_kind='order_storno' THEN ':storno' ELSE ':false' END
   AND NOT m.data ? 'requested_by';
 END IF;
 IF commitment THEN RETURN 'commitment'; END IF;
 RETURN CASE WHEN m.message_kind IN ('registration','sign_in','reset_password','google_mailbox','gotrue') THEN 'auth' ELSE 'ordinary' END;
END $$;
REVOKE ALL ON FUNCTION public.email_admission_class_v1(public.email_messages) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.admit_email_intent_v1(p_message bigint,p_recheck boolean DEFAULT false) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE m public.email_messages; policy jsonb; scopes jsonb; costs jsonb; r jsonb;
 is_auth boolean; unit_count bigint; org_count bigint; unit_bytes bigint; org_bytes bigint; growth bigint:=0; policies jsonb;
BEGIN
 SELECT * INTO STRICT m FROM public.email_messages WHERE id=p_message;
 policies:=public.abuse_policy_bundle_v1(ARRAY['email.payload','email.actor','email.backlog','email.auth.backlog','email.auth','email.ordinary'],m.unit,m.organization);
 IF m.unit IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.units WHERE id=m.unit AND organization=m.organization) THEN
  RAISE invalid_parameter_value USING MESSAGE='email_scope_mismatch'; END IF;
 scopes:=jsonb_build_object('unit',m.unit,'organization',m.organization,'global','all',
  'actor',m.producer_actor,'recipient',public.abuse_recipient_key_v1(coalesce(m.recipient,(SELECT email_readonly FROM public.user_info WHERE id=m.recipient_user))));
 PERFORM public.abuse_charge_v1(policies->'email.payload',scopes,
  jsonb_build_object('email.payload.bytes',octet_length(m.data::text)+coalesce(octet_length(m.prepared::text),0)));
 -- Neither caller priority nor request data can claim the reserved class.
 IF public.email_admission_class_v1(m)='commitment' THEN
  UPDATE public.email_messages SET admission_class='commitment',priority=5 WHERE id=m.id;
  RETURN;
 END IF;
 IF NOT p_recheck AND m.producer_actor IS NOT NULL THEN
  PERFORM public.abuse_charge_v1(policies->'email.actor',scopes);
 END IF;
 is_auth:=public.email_admission_class_v1(m)='auth';
 UPDATE public.email_messages SET admission_class=CASE WHEN is_auth THEN 'auth' ELSE 'ordinary' END WHERE id=m.id;
 policy:=policies->(CASE WHEN is_auth THEN 'email.auth.backlog' ELSE 'email.backlog' END);
 -- Null Unit auth has an explicit tenant/global class, never a synthetic Unit.
 IF m.unit IS NULL THEN policy:=jsonb_set(policy,'{rules}',(SELECT jsonb_agg(value) FROM jsonb_array_elements(policy->'rules') WHERE value->>'scope_kind'<>'unit')); END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(policy->'rules') ORDER BY value->>'rule_key' LOOP
  IF r->>'kind' IN ('bytes','duration') THEN CONTINUE; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('abuse:'||(r->>'rule_key')||':'||(scopes->>(r->>'scope_kind')),0));
 END LOOP;
 -- Pending partial indexes exclude delivery history. Include blocked/future/unknown.
 SELECT count(*) FILTER(WHERE unit=m.unit),count(*),
  coalesce(sum(octet_length(data::text)+coalesce(octet_length(prepared::text),0)) FILTER(WHERE unit=m.unit),0),
  coalesce(sum(octet_length(data::text)+coalesce(octet_length(prepared::text),0)),0)
 INTO unit_count,org_count,unit_bytes,org_bytes FROM public.email_messages
 WHERE organization=m.organization AND admission_class=CASE WHEN is_auth THEN 'auth' ELSE 'ordinary' END AND workflow_state IN ('pending','blocked','preparing','sending','retry_wait','unknown');
 costs:=jsonb_build_object('email.auth.backlog.organization',org_count,'email.backlog.unit',unit_count,'email.backlog.organization',org_count,
  'email.backlog.unit.bytes',unit_bytes,'email.backlog.organization.bytes',org_bytes);
 PERFORM public.abuse_charge_v1(policy,scopes,costs);
 IF p_recheck THEN RETURN; END IF;
 policy:=policies->(CASE WHEN is_auth THEN 'email.auth' ELSE 'email.ordinary' END);
 IF NOT is_auth AND m.unit IS NULL THEN
  -- System producers without a Unit retain tenant and recipient bounds.
  policy:=jsonb_set(policy,'{rules}',(SELECT jsonb_agg(value) FROM jsonb_array_elements(policy->'rules') WHERE value->>'scope_kind'<>'unit'));
 END IF;
 IF NOT is_auth AND m.unit IS NOT NULL THEN
  SELECT coalesce(verified_orders,0) INTO growth FROM public.abuse_unit_evidence
   WHERE unit=m.unit AND measured_at>statement_timestamp()-interval '15 minutes';
  growth:=coalesce(growth,0);
 END IF;
 PERFORM public.abuse_charge_v1(policy,scopes,jsonb_build_object('growth',growth));
END $$;
REVOKE ALL ON FUNCTION public.admit_email_intent_v1(bigint,boolean) FROM PUBLIC,anon,authenticated,service_role;

-- Separate committed preparation budget limits rendering before final enqueue.
CREATE OR REPLACE FUNCTION public.admit_email_preparation_v1(p_organization bigint,p_occasion bigint,p_unit bigint,p_recipient text)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.require_service_role();
 IF NOT EXISTS(SELECT 1 FROM public.organizations WHERE id=p_organization)
 OR (p_unit IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.units WHERE id=p_unit AND organization=p_organization))
 OR (p_occasion IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=p_occasion AND organization=p_organization AND (p_unit IS NULL OR unit=p_unit)))
 OR p_recipient IS NULL OR length(p_recipient)>320 THEN RAISE invalid_parameter_value USING MESSAGE='email_preparation_scope'; END IF;
 RETURN public.abuse_charge_v1(public.abuse_effective_rules_v1('email.prepare',p_unit,p_organization),
  jsonb_build_object('organization',p_organization,'recipient',public.abuse_recipient_key_v1(p_recipient)), '{}',true);
END $$;
REVOKE ALL ON FUNCTION public.admit_email_preparation_v1(bigint,bigint,bigint,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.admit_email_preparation_v1(bigint,bigint,bigint,text) TO service_role;

CREATE OR REPLACE FUNCTION public.admit_order_creation_v1(p_occasion bigint) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE occ public.occasions; policy jsonb; scopes jsonb; costs jsonb; r jsonb;
BEGIN
 SELECT * INTO STRICT occ FROM public.occasions WHERE id=p_occasion;
 policy:=public.abuse_effective_rules_v1('order.creation',occ.unit,occ.organization);
 scopes:=jsonb_build_object('unit',occ.unit,'organization',occ.organization);
 FOR r IN SELECT value FROM jsonb_array_elements(policy->'rules') ORDER BY value->>'rule_key' LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('abuse:'||(r->>'rule_key')||':'||(scopes->>(r->>'scope_kind')),0));
 END LOOP;
 SELECT jsonb_build_object('order.outstanding.unit',count(*) FILTER(WHERE oc.unit=occ.unit)+1,
  'order.outstanding.organization',count(*)+1) INTO costs
 FROM eshop.orders o JOIN public.occasions oc ON oc.id=o.occasion
 WHERE oc.organization=occ.organization AND o.state IN ('ordered','created','expired','waitlisted','paid');
 PERFORM public.abuse_charge_v1(policy,scopes,costs);
END $$;
REVOKE ALL ON FUNCTION public.admit_order_creation_v1(bigint) FROM PUBLIC,anon,authenticated,service_role;

-- Periodic local maintenance, not a query per mail/request. The source is
-- positive signed-bank evidence, distinct orders, and a capped sample/count.
CREATE OR REPLACE FUNCTION public.refresh_abuse_unit_evidence_v1() RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE u record; cap bigint; n integer:=0; verified bigint;
BEGIN
 PERFORM public.require_service_role();
 SELECT hard_cap/greatest(growth_increment,1)+1 INTO cap FROM public.abuse_policy_rules WHERE rule_key='email.ordinary.unit.day';
 IF cap IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 FOR u IN SELECT units.id FROM public.units LEFT JOIN public.abuse_unit_evidence e ON e.unit=units.id
  WHERE e.measured_at IS NULL OR e.measured_at<statement_timestamp()-interval '5 minutes'
  ORDER BY e.measured_at NULLS FIRST,units.id LIMIT 20 LOOP
  IF NOT pg_try_advisory_xact_lock(hashtextextended('abuse-growth:'||u.id,0)) THEN CONTINUE; END IF;
  SELECT count(*) INTO verified FROM (
   SELECT ord.id FROM eshop.orders ord JOIN public.occasions occ ON occ.id=ord.occasion
   WHERE occ.unit=u.id AND ord.state IN ('paid','sent') AND ord.price>0
   AND (SELECT coalesce(sum(t.amount),0) FROM eshop.transactions t
    WHERE t.payment_info=ord.payment_info AND t.currency=ord.currency_code
     AND EXISTS(SELECT 1 FROM eshop.bank_transaction_identities i WHERE i.transaction_id=t.id))>=ord.price LIMIT cap
  ) proof;
  INSERT INTO public.abuse_unit_evidence VALUES(u.id,verified,statement_timestamp())
   ON CONFLICT(unit) DO UPDATE SET verified_orders=excluded.verified_orders,measured_at=excluded.measured_at;
  n:=n+1;
 END LOOP;
 RETURN n;
END $$;
REVOKE ALL ON FUNCTION public.refresh_abuse_unit_evidence_v1() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.refresh_abuse_unit_evidence_v1() TO service_role;


-- Source: database/functions/abuse/scan.sql
-- Domain callers verify the actual scan secret. Invalid inputs never gain a new
-- arbitrary limiter key: only an existing occasion or the shared unknown scope.
-- Return rejection rather than raise so failed proof consumption can commit.
-- Only the gateway-owned header is an IP identity; the gateway must replace it.
-- Missing/malformed context shares a bounded fail-closed unknown source.
CREATE OR REPLACE FUNCTION public.abuse_request_source_v1() RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE source text;
BEGIN
 BEGIN source:=((nullif(current_setting('request.headers',true),'')::jsonb)->>'x-festapp-client-ip')::inet::text;
 EXCEPTION WHEN invalid_text_representation THEN source:=NULL; END;
 RETURN public.abuse_recipient_key_v1(coalesce(source,'unknown'));
END $$;
REVOKE ALL ON FUNCTION public.abuse_request_source_v1() FROM PUBLIC,anon,authenticated,service_role;

-- Check before comparing any proof, with the same locks used by consumption.
-- Authenticated order viewers have an available recovery path during anonymous
-- source exhaustion; a correct staff secret alone never bypasses the gate.
CREATE OR REPLACE FUNCTION public.check_scan_attempt_budget_v1(p_occasion bigint DEFAULT NULL)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE policies jsonb; policy jsonb; family text; scopes jsonb;
BEGIN
 IF auth.uid() IS NOT NULL AND p_occasion IS NOT NULL AND public.get_is_editor_order_view_on_occasion(p_occasion) THEN RETURN true; END IF;
 policies:=public.abuse_policy_bundle_v1(ARRAY['scan.invalid.global','scan.invalid.source'],NULL,NULL);
 scopes:=jsonb_build_object('global','all','recipient',public.abuse_request_source_v1());
 FOREACH family IN ARRAY ARRAY['scan.invalid.global','scan.invalid.source'] LOOP
  policy:=policies->family;
  -- A zero-cost check must deny at the limit, not only after one more guess.
  policy:=jsonb_set(policy,'{rules}',(SELECT jsonb_agg(jsonb_set(r,'{base_limit}',to_jsonb((r->>'base_limit')::bigint-1))) FROM jsonb_array_elements(policy->'rules') r));
  IF NOT public.abuse_charge_v1(policy,scopes,(SELECT jsonb_object_agg(r->>'rule_key',0) FROM jsonb_array_elements(policy->'rules') r),true) THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.check_scan_attempt_budget_v1(bigint) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.admit_scan_access_v1(p_occasion bigint,p_authorized boolean)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE un bigint; org bigint;
BEGIN
 SELECT unit,organization INTO un,org FROM public.occasions WHERE id=p_occasion;
 IF p_authorized IS DISTINCT FROM true OR un IS NULL THEN
  IF public.abuse_charge_v1(public.abuse_effective_rules_v1('scan.invalid.global',NULL,NULL),jsonb_build_object('global','all'),'{}',true) THEN
   PERFORM public.abuse_charge_v1(public.abuse_effective_rules_v1('scan.invalid.source',NULL,NULL),jsonb_build_object('recipient',public.abuse_request_source_v1()),'{}',true);
  END IF;
  RETURN false;
 END IF;
 RETURN public.abuse_charge_v1(public.abuse_effective_rules_v1('scan.operation',un,org),
  jsonb_build_object('unit',un,'organization',org),'{}',true);
END $$;
REVOKE ALL ON FUNCTION public.admit_scan_access_v1(bigint,boolean) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.admit_scan_password_reset_v1(p_occasion bigint,p_user uuid)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE un bigint; org bigint;
BEGIN
 SELECT unit,organization INTO un,org FROM public.occasions WHERE id=p_occasion;
 IF un IS NULL OR p_user IS NULL THEN RETURN false; END IF;
 RETURN public.abuse_charge_v1(public.abuse_effective_rules_v1('scan.password',un,org),
  jsonb_build_object('unit',un,'recipient',public.abuse_recipient_key_v1(p_user::text)),'{}',true);
END $$;
REVOKE ALL ON FUNCTION public.admit_scan_password_reset_v1(bigint,uuid) FROM PUBLIC,anon,authenticated,service_role;
CREATE INDEX IF NOT EXISTS occasions_hidden_scan_secret_idx ON public.occasions_hidden(secret);


-- Source: database/functions/abuse/orders.sql
-- Caller owns authorization and its existing receipt. This helper does not
-- cancel, refund, reprice or delete anything and has no external execution grant.
CREATE OR REPLACE FUNCTION public.admit_order_mutation_v1(p_occasion bigint,p_items bigint)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE un bigint; org bigint;
BEGIN
 IF auth.uid() IS NULL THEN RAISE insufficient_privilege USING MESSAGE='order actor required'; END IF;
 SELECT unit,organization INTO STRICT un,org FROM public.occasions WHERE id=p_occasion;
 PERFORM public.abuse_charge_v1(public.abuse_effective_rules_v1('order.mutation',un,org),
  jsonb_build_object('actor',auth.uid(),'unit',un,'organization',org),jsonb_build_object('order.mutation.items',p_items));
END $$;
REVOKE ALL ON FUNCTION public.admit_order_mutation_v1(bigint,bigint) FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/notifications/dispatch_log_notification.sql
-- The existing notification log is the durable intent; dispatch is explicit in
-- its domain command, after receipt/auth/admission. No row hook is installed.
CREATE TABLE public.notification_runtime (
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),
 endpoint text CHECK(endpoint ~ '^https://[^/]+/functions/v1/notify$')
);
INSERT INTO public.notification_runtime(singleton) VALUES(true);
ALTER TABLE public.notification_runtime ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.notification_runtime FROM PUBLIC,anon,authenticated;
GRANT SELECT,UPDATE ON public.notification_runtime TO service_role;
-- Adopt the existing server-owned destination, without sending anything.
UPDATE public.notification_runtime SET endpoint=(
 SELECT split_part(encode(tgargs,'escape'),E'\\000',1) FROM pg_trigger
 WHERE tgrelid='public.log_notifications'::regclass AND tgname='push_log_notifications' AND NOT tgisinternal
) WHERE singleton;
DROP TRIGGER IF EXISTS push_log_notifications ON public.log_notifications;
DROP FUNCTION IF EXISTS public.deliver_log_notification_v1();

CREATE OR REPLACE FUNCTION public.dispatch_log_notification_v1(p_notification uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE endpoint text; webhook_token text; message jsonb;
BEGIN
 SELECT r.endpoint INTO endpoint FROM public.notification_runtime r WHERE singleton;
 IF endpoint IS NULL THEN RETURN; END IF; -- Unconfigured local/rehearsal runtime.
 SELECT decrypted_secret INTO webhook_token FROM vault.decrypted_secrets WHERE name='festapp_notify_webhook_token_v1';
 IF webhook_token IS NULL OR length(webhook_token)<32 THEN RAISE configuration_limit_exceeded USING MESSAGE='notification webhook token missing'; END IF;
 SELECT to_jsonb(n) INTO message FROM public.log_notifications n WHERE id=p_notification;
 IF message IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='notification intent missing'; END IF;
 PERFORM net.http_post(url:=endpoint,headers:=jsonb_build_object('Authorization','Bearer '||webhook_token,'Content-Type','application/json'),
  body:=jsonb_build_object('record',message),timeout_milliseconds:=4000);
END $$;
REVOKE ALL ON FUNCTION public.dispatch_log_notification_v1(uuid) FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/seed/triggers.sql
CREATE OR REPLACE FUNCTION public.setup_triggers(p_project_url text)
RETURNS void
LANGUAGE plpgsql
SET search_path = ''
AS $function$
DECLARE
  relation_name text;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' AND session_user <> 'postgres' THEN
    RAISE EXCEPTION 'Access Denied: Service role required.';
  END IF;
  IF p_project_url !~ '^https://[^/]+$' THEN
    RAISE EXCEPTION 'Project URL must be an HTTPS origin';
  END IF;

  FOREACH relation_name IN ARRAY ARRAY[
    'events', 'icons', 'information', 'news', 'occasions', 'places',
    'user_info', 'speakers', 'speaker_topics', 'cleaning_reports'
  ] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS handle_updated_at ON public.%I', relation_name);
    EXECUTE format(
      'CREATE TRIGGER handle_updated_at BEFORE UPDATE ON public.%I '
      'FOR EACH ROW EXECUTE FUNCTION extensions.moddatetime(''updated_at'')',
      relation_name
    );
  END LOOP;

  -- Notification delivery is an explicit domain-command operation.
  UPDATE public.notification_runtime SET endpoint=p_project_url||'/functions/v1/notify' WHERE singleton;
END
$function$;

REVOKE ALL ON FUNCTION public.setup_triggers(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.setup_triggers(text) TO service_role;


-- Source: database/functions/abuse/push.sql
-- Reuse the existing notification log and its UUID. No queue or sender is added.
-- Only canonical stored content can reach the existing signed webhook adapter.
CREATE OR REPLACE FUNCTION public.charge_notification_intent_v1(p_occasion bigint,p_actor uuid,p_to jsonb,p_heading text,p_content text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE o public.occasions; policy jsonb; cap bigint; targets bigint; recipients jsonb;
BEGIN
 SELECT * INTO STRICT o FROM public.occasions WHERE id=p_occasion;
 policy:=public.abuse_effective_rules_v1('push.delivery',o.unit,o.organization);
 SELECT (r->>'base_limit')::bigint INTO cap FROM jsonb_array_elements(policy->'rules') r WHERE r->>'rule_key'='push.delivery.targets';
 IF cap IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 IF p_to IS NOT NULL AND p_to<>'null'::jsonb THEN
  recipients:=CASE jsonb_typeof(p_to) WHEN 'array' THEN p_to WHEN 'string' THEN jsonb_build_array(p_to) ELSE NULL END;
  IF recipients IS NULL OR jsonb_array_length(recipients)=0 OR jsonb_array_length(recipients)>cap THEN RAISE invalid_parameter_value USING MESSAGE='invalid notification recipients'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(recipients) r WHERE NOT EXISTS(SELECT 1 FROM public.occasion_users ou WHERE ou.occasion=o.id AND ou."user"::text=r)) THEN
   RAISE insufficient_privilege USING MESSAGE='notification recipient outside occasion'; END IF;
  SELECT count(DISTINCT r) INTO targets FROM jsonb_array_elements_text(recipients) r;
 ELSE
  SELECT count(*) INTO targets FROM (SELECT 1 FROM public.occasion_users WHERE occasion=o.id LIMIT cap+1) audience;
 END IF;
 PERFORM public.abuse_charge_v1(policy,jsonb_build_object('actor',p_actor,'unit',o.unit,'organization',o.organization,'global','all'),
  jsonb_build_object('push.targets.unit.day',targets,'push.targets.organization.day',targets,'push.targets.global.day',targets,
   'push.delivery.targets',targets,'push.payload.bytes',octet_length(jsonb_build_object('heading',p_heading,'content',p_content,'to',p_to)::text),'push.delivery.age.seconds',0));
END $$;
REVOKE ALL ON FUNCTION public.charge_notification_intent_v1(bigint,uuid,jsonb,text,text) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.enqueue_notification_v1(p_occasion bigint,p_heading text,p_content text,p_to jsonb DEFAULT NULL,p_data jsonb DEFAULT NULL)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE notification uuid;
BEGIN
 IF auth.uid() IS NULL OR public.get_is_editor_on_occasion(p_occasion) IS DISTINCT FROM true THEN RAISE insufficient_privilege USING MESSAGE='notification editor required'; END IF;
 IF p_data IS NOT NULL AND (jsonb_typeof(p_data)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_data) k WHERE k<>'path')
  OR coalesce(p_data->>'path','news') NOT IN ('news','cleaning')) THEN RAISE invalid_parameter_value USING MESSAGE='invalid notification data'; END IF;
 PERFORM public.charge_notification_intent_v1(p_occasion,auth.uid(),p_to,p_heading,p_content);
 INSERT INTO public.log_notifications(occasion,organization,user_id,"to",heading,content,data,abuse_admitted_at)
 SELECT p_occasion,organization,auth.uid(),p_to,p_heading,p_content,p_data,statement_timestamp() FROM public.occasions WHERE id=p_occasion RETURNING id INTO notification;
 PERFORM public.dispatch_log_notification_v1(notification);
 RETURN notification;
END $$;
REVOKE ALL ON FUNCTION public.enqueue_notification_v1(bigint,text,text,jsonb,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.enqueue_notification_v1(bigint,text,text,jsonb,jsonb) TO authenticated;

CREATE OR REPLACE FUNCTION public.admit_notification_delivery_v1(p_notification uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE n public.log_notifications; o public.occasions; policy jsonb; max_age bigint;
BEGIN
 PERFORM public.require_service_role();
 SELECT * INTO n FROM public.log_notifications WHERE id=p_notification FOR UPDATE;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='notification unavailable'; END IF;
 SELECT * INTO STRICT o FROM public.occasions WHERE id=n.occasion;
 IF n.organization IS DISTINCT FROM o.organization THEN RAISE insufficient_privilege USING MESSAGE='notification scope mismatch'; END IF;
 policy:=public.abuse_effective_rules_v1('push.delivery',o.unit,o.organization);
 SELECT (r->>'base_limit')::bigint INTO max_age FROM jsonb_array_elements(policy->'rules') r WHERE r->>'rule_key'='push.delivery.age.seconds';
 IF max_age IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 IF n.created_at>statement_timestamp() OR n.created_at<statement_timestamp()-make_interval(secs=>max_age::integer) THEN
  RAISE invalid_parameter_value USING MESSAGE='notification expired'; END IF;
 IF n.abuse_admitted_at IS NULL THEN
  PERFORM public.charge_notification_intent_v1(n.occasion,n.user_id,n."to",n.heading,n.content);
  UPDATE public.log_notifications SET abuse_admitted_at=statement_timestamp() WHERE id=n.id;
 END IF;
 IF NOT public.abuse_charge_v1(public.abuse_effective_rules_v1('push.dispatch',o.unit,o.organization),jsonb_build_object('unit',o.unit,'global','all'),'{}',true) THEN RETURN jsonb_build_object('allowed',false); END IF;
 RETURN to_jsonb(n)||jsonb_build_object('occasion_link',o.link,'allowed',true);
END $$;
REVOKE ALL ON FUNCTION public.admit_notification_delivery_v1(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.admit_notification_delivery_v1(uuid) TO service_role;

-- Current clients use enqueue_notification_v1; REST INSERT cannot silently
-- depend on a row trigger for delivery or run admission from an RLS predicate.
DROP POLICY IF EXISTS "Enable insert for editors" ON public.log_notifications;
REVOKE INSERT ON public.log_notifications FROM PUBLIC,anon,authenticated;
REVOKE INSERT(occasion,organization,"to",heading,content,data) ON public.log_notifications FROM PUBLIC,anon,authenticated;


-- Source: database/functions/notifications/publication.sql
-- Canonical publication ordering retained; admission precedes both existing push paths.

CREATE OR REPLACE FUNCTION public.complete_client_sync_publication_classes_v1(p_scope_type text, p_scope_id bigint, p_release_revision bigint, p_manifest jsonb, p_manifest_url text, p_manifest_sha256 text, p_manifest_bytes bigint, p_live jsonb, p_head_json jsonb, p_head_etag text, p_catalog_claim_tokens uuid[], p_live_claim_tokens uuid[])
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path = public, extensions
AS $function$
DECLARE v_head public.client_sync_public_heads%ROWTYPE; v_component record;
  v_next_catalog bigint := (p_head_json#>>'{catalog,revision}')::bigint;
  v_next_live bigint := (p_head_json#>>'{live,revision}')::bigint;
  v_content_revision bigint; v_notification uuid;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  SELECT * INTO v_head FROM public.client_sync_public_heads
    WHERE scope_type=p_scope_type AND scope_id=p_scope_id FOR UPDATE;
  IF FOUND AND (v_next_catalog < COALESCE(v_head.release_revision,-1)
      OR COALESCE(v_next_live,-1) < COALESCE(v_head.live_revision,-1)
      OR (v_next_catalog = v_head.release_revision
          AND v_next_live IS NOT DISTINCT FROM v_head.live_revision
          AND v_head.head_json IS DISTINCT FROM p_head_json)) THEN
    RETURN false;
  END IF;
  IF p_release_revision IS NOT NULL THEN
    IF p_manifest IS NULL OR p_manifest_sha256 IS NULL
       OR p_release_revision <> v_next_catalog THEN RAISE EXCEPTION 'invalid catalog completion'; END IF;
    INSERT INTO public.client_sync_release_manifests
      (scope_type,scope_id,release_revision,manifest,artifact_url,sha256,byte_size)
    VALUES (p_scope_type,p_scope_id,p_release_revision,p_manifest,p_manifest_url,
      p_manifest_sha256,p_manifest_bytes) ON CONFLICT DO NOTHING;
    FOR v_component IN SELECT key,value FROM jsonb_each(p_manifest->'components') LOOP
      INSERT INTO public.client_sync_publications
        (component,scope_type,scope_id,published_revision,media_type,artifact_url,sha256,byte_size)
      VALUES (v_component.key,p_scope_type,p_scope_id,
        (v_component.value->>'revision')::bigint,v_component.value->>'mediaType',
        v_component.value->>'url',v_component.value->>'sha256',(v_component.value->>'bytes')::bigint)
      ON CONFLICT DO NOTHING;
    END LOOP;
  END IF;
  IF p_live IS NOT NULL THEN
    INSERT INTO public.client_sync_publications
      (component,scope_type,scope_id,published_revision,media_type,artifact_url,sha256,byte_size)
    VALUES ('live_public',p_scope_type,p_scope_id,(p_live->>'revision')::bigint,
      p_live->>'mediaType',p_live->>'url',p_live->>'sha256',(p_live->>'bytes')::bigint)
    ON CONFLICT DO NOTHING;
  END IF;
  INSERT INTO public.client_sync_public_heads
    (scope_type,scope_id,release_revision,manifest_sha256,live_revision,live_sha256,head_etag,head_json)
  VALUES (p_scope_type,p_scope_id,v_next_catalog,p_head_json#>>'{catalog,sha256}',
    v_next_live,p_head_json#>>'{live,sha256}',p_head_etag,p_head_json)
  ON CONFLICT (scope_type,scope_id) DO UPDATE SET
    release_revision=EXCLUDED.release_revision,manifest_sha256=EXCLUDED.manifest_sha256,
    live_revision=EXCLUDED.live_revision,live_sha256=EXCLUDED.live_sha256,
    head_etag=EXCLUDED.head_etag,head_json=EXCLUDED.head_json,updated_at=now();

  -- R2 artifacts and the accepted public head already exist at this point.
  -- Moving ready rows into log_notifications is atomic with recording that head;
  -- explicit dispatch therefore cannot outrun content_catalog.
  v_content_revision:=(p_manifest#>>'{components,content_catalog,revision}')::bigint;
  IF p_scope_type='occasion' AND v_content_revision IS NOT NULL THEN
    FOR v_notification IN WITH ready AS (
      DELETE FROM public.news_notification_outbox q
      WHERE q.occasion=p_scope_id
        AND q.required_content_revision<=v_content_revision
      RETURNING q.*
    )
    INSERT INTO public.log_notifications
      (id,occasion,organization,user_id,"to",heading,content,data,created_at,abuse_admitted_at)
    SELECT r.id,r.occasion,r.organization,r.user_id,r."to",r.heading,r.content,
      r.data,r.created_at,r.abuse_admitted_at
    FROM ready r
    ON CONFLICT (id) DO NOTHING RETURNING id LOOP
      PERFORM public.dispatch_log_notification_v1(v_notification);
    END LOOP;
  END IF;

  DELETE FROM public.client_projection_dirty_keys
    WHERE claim_token=ANY(COALESCE(p_catalog_claim_tokens,'{}')) AND component<>'live_public';
  DELETE FROM public.client_projection_dirty_keys
    WHERE claim_token=ANY(COALESCE(p_live_claim_tokens,'{}')) AND component='live_public';
  RETURN true;
END; $function$;


CREATE OR REPLACE FUNCTION public.publish_news_client_sync_v1(p_occasion bigint, p_add_to_news boolean, p_news_message text, p_send_notification boolean, p_notification_heading text, p_notification_content text, p_recipients jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_notification uuid; v_actor uuid:=auth.uid(); v_organization bigint; v_begin jsonb; v_hash text;
  v_id bigint; v_version bigint:=0; v_entity jsonb; v_items jsonb:='[]'::jsonb;
  v_is_publishable boolean; v_response jsonb; v_required_revision bigint;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  SELECT o.organization,NOT o.is_hidden INTO v_organization,v_is_publishable
    FROM public.occasions o WHERE o.id=p_occasion;
  IF v_organization IS NULL OR NOT COALESCE(p_add_to_news,false)
      AND NOT COALESCE(p_send_notification,false)
    OR p_add_to_news AND (p_news_message IS NULL
      OR octet_length(p_news_message) NOT BETWEEN 1 AND 524288)
    OR p_send_notification AND (p_notification_content IS NULL
      OR octet_length(p_notification_content)>65536
      OR octet_length(COALESCE(p_notification_heading,''))>2048
      OR p_recipients IS NOT NULL AND (jsonb_typeof(p_recipients)<>'array'
        OR jsonb_array_length(p_recipients)>5000
        OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_recipients) value
          WHERE jsonb_typeof(value)<>'string'
            OR octet_length(value#>>'{}')>512))) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid news publication'; END IF;
  IF COALESCE(p_add_to_news,false) AND COALESCE(p_send_notification,false)
      AND NOT v_is_publishable THEN
    RAISE invalid_parameter_value
      USING MESSAGE='news push requires a publicly publishable occasion';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'addToNews',p_add_to_news,'newsMessage',p_news_message,
    'sendNotification',p_send_notification,'notificationHeading',p_notification_heading,
    'notificationContent',p_notification_content,'recipients',p_recipients)::text,
    'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'content.news.publish',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF coalesce(p_send_notification,false) THEN PERFORM public.charge_notification_intent_v1(p_occasion,v_actor,p_recipients,p_notification_heading,p_notification_content); END IF;
  IF COALESCE(p_add_to_news,false) THEN
    INSERT INTO public.news(message,created_by,occasion)
      VALUES (p_news_message,v_actor,p_occasion) RETURNING id INTO v_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('news','occasion',p_occasion,v_id::text,v_version);
    SELECT to_jsonb(n)||jsonb_build_object('aggregate_version',v_version)
      INTO v_entity FROM public.news n WHERE n.id=v_id;
    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'entityType','news','entityId',v_id,'operation','insert','safeLabel','News',
      'changedFields',jsonb_build_array('message')));
  END IF;
  IF COALESCE(p_send_notification,false) THEN
    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'entityType','notification','entityId',NULL,'operation','publish',
      'safeLabel','Notification','changedFields',jsonb_build_array('delivery_request')));
  END IF;

  -- A notification-only test has no news publication to wait for.
  IF COALESCE(p_send_notification,false) AND NOT COALESCE(p_add_to_news,false) THEN
    INSERT INTO public.log_notifications
      (occasion,organization,user_id,"to",heading,content,data,abuse_admitted_at)
    VALUES (p_occasion,v_organization,v_actor,p_recipients,
      p_notification_heading,p_notification_content,jsonb_build_object('path','news'),statement_timestamp()) RETURNING id INTO v_notification;
    PERFORM public.dispatch_log_notification_v1(v_notification);
  END IF;

  v_response:=public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'content.news.publish','content',v_items,
    CASE WHEN COALESCE(p_add_to_news,false) AND v_is_publishable
      THEN ARRAY['content_catalog'] ELSE '{}'::text[] END,'[]','[]',
    jsonb_build_object('version',v_version,'news',v_entity,
      'notificationQueued',COALESCE(p_send_notification,false)));

  IF COALESCE(p_add_to_news,false) AND COALESCE(p_send_notification,false) THEN
    SELECT c.resulting_revision INTO v_required_revision
    FROM public.client_commit_components c
    WHERE c.commit_id=(v_response#>>'{mutation,commitId}')::uuid
      AND c.component='content_catalog' AND c.scope_type='occasion'
      AND c.scope_id=p_occasion AND c.user_id IS NULL;
    IF v_required_revision IS NULL THEN
      RAISE EXCEPTION 'news publication did not produce a content revision';
    END IF;
    INSERT INTO public.news_notification_outbox
      (command_id,occasion,organization,user_id,required_content_revision,
       "to",heading,content,data,abuse_admitted_at)
    VALUES (p_command_id,p_occasion,v_organization,v_actor,v_required_revision,
      p_recipients,p_notification_heading,p_notification_content,
      jsonb_build_object('path','news'),statement_timestamp());
  END IF;
  RETURN v_response;
END; $function$;


