-- Source: database/functions/cleaning/report_cleaning_issue.sql
-- Cleaning service — participant reports a problem on a toilet.
-- SECURITY DEFINER: participants have no direct write access to cleaning_reports
-- or log_notifications, so all validation, insert and crew notification happen
-- here. Envelope {code, message, data} like submit_event_feedback.
--
-- Behaviour:
--   * only approved occasion participants; place must exist, belong to the
--     occasion and be of place_type "toilet"; feature "cleaning" must be
--     enabled on the occasion.
--   * dedup: an already-open report of the same (place, problem_type) is NOT
--     duplicated and sends NO extra notification — returns 200 data.duplicate=true
--     and appends the reporter's note to the existing row so it is not lost.
--   * rate limit: max 5 reports per user per 15 minutes -> 429.
--   * on a fresh report, inserts a log_notifications row addressed to the crew
--     (data.path = 'cleaning' so the push deep-links to the Cleaning page).
CREATE OR REPLACE FUNCTION public.report_cleaning_issue(
  place_id bigint,
  problem_type text,
  note text DEFAULT NULL
) RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public, extensions
AS $$
DECLARE
  v_user uuid := auth.uid();
  v_note text := NULLIF(btrim(COALESCE(note, '')), '');
  v_place public.places%ROWTYPE;
  v_occasion bigint;
  v_organization bigint;
  v_type_label text;
  v_existing public.cleaning_reports%ROWTYPE;
  v_report public.cleaning_reports%ROWTYPE;
  v_crew jsonb;
  v_notification_deferred boolean:=false;
  v_notification uuid;
  v_policy jsonb; v_new_data jsonb;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('code', 401, 'message', 'Sign in is required to report a cleaning issue');
  END IF;

  -- Problem types — keep in sync with: cleaning_reports.problem_type CHECK
  -- (database/tables/tables.sql), CleaningStatusHelper (cleaning_status.dart)
  -- and the report dialog (cleaning_report_dialog.dart).
  IF problem_type NOT IN ('paper', 'hygiene', 'contamination') THEN
    RETURN jsonb_build_object('code', 400, 'message', 'Invalid problem type');
  END IF;

  IF char_length(COALESCE(v_note, '')) > 2000 THEN
    RETURN jsonb_build_object('code', 413, 'message', 'Note is too long');
  END IF;

  SELECT * INTO v_place FROM public.places WHERE id = place_id;
  IF NOT FOUND OR v_place.occasion IS NULL THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Toilet not found');
  END IF;

  v_occasion := v_place.occasion;

  IF NOT EXISTS (
    SELECT 1
    FROM public.occasion_users
    WHERE occasion = v_occasion
      AND "user" = v_user
      AND is_approved = true
  ) THEN
    RETURN jsonb_build_object('code', 403, 'message', 'Approved occasion participation is required');
  END IF;

  -- Blocked reporters (anti-spam hard ban) cannot file reports on this occasion.
  -- This is the source of truth; the UI also greys the report action out via the
  -- is_blocked flag returned by get_cleaning_status.
  IF EXISTS (
    SELECT 1 FROM public.occasion_users
    WHERE occasion = v_occasion
      AND "user" = v_user
      AND is_cleaning_blocked = true
  ) THEN
    RETURN jsonb_build_object('code', 403, 'message', 'Reporting has been disabled for your account');
  END IF;

  -- Place must be flagged as a toilet (places.type = 'toilet'). This is set by
  -- the "WC / Úklid" checkbox in the admin Places grid — no place_types catalog
  -- row is required.
  IF v_place.type IS DISTINCT FROM 'toilet' THEN
    RETURN jsonb_build_object('code', 400, 'message', 'Place is not a toilet');
  END IF;

  -- Feature "cleaning" must be enabled on the occasion (occasions.features).
  IF NOT EXISTS (
    SELECT 1
    FROM public.occasions o
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(o.features, '[]'::jsonb)) feature
    WHERE o.id = v_occasion
      AND feature->>'code' = 'cleaning'
      AND LOWER(COALESCE(feature->>'is_enabled', 'false')) = 'true'
  ) THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Cleaning feature is not enabled for this occasion');
  END IF;

  -- Committed accepted work, including appended duplicate notes, shares one
  -- actor identity. Removing a report cannot replenish its rolling budget.
  BEGIN
    v_policy:=public.abuse_effective_rules_v1('cleaning.report',NULL,NULL);
    PERFORM public.abuse_charge_v1(v_policy,
      jsonb_build_object('actor',v_user),jsonb_build_object('cleaning.note.bytes',octet_length(coalesce(v_note,'')), 'cleaning.report.bytes',0));
  EXCEPTION WHEN SQLSTATE 'PT429' THEN RETURN jsonb_build_object('code',429,'message','Too many reports, please wait a moment'); END;
  PERFORM pg_advisory_xact_lock(hashtextextended('cleaning-report:'||place_id::text||':'||problem_type,0));

  -- Push-notification labels are deliberately Czech-only (the crew is Czech;
  -- localizing push messages is out of scope). Keep the type list in sync — see
  -- the problem_type check above.
  v_type_label := CASE problem_type
    WHEN 'paper'         THEN 'Nedostatek toaletního papíru'
    WHEN 'hygiene'       THEN 'Nedostatek hygienických potřeb'
    WHEN 'contamination' THEN 'Totální znečištění ☣️'
  END;

  -- Dedup: reuse an open report of the same place + type.
  SELECT cr.* INTO v_existing
  FROM public.cleaning_reports cr
  WHERE cr.place = place_id
    AND cr.problem_type = report_cleaning_issue.problem_type
    AND cr.resolved_at IS NULL
  ORDER BY cr.created_at ASC
  LIMIT 1;

  IF FOUND THEN
    IF v_note IS NOT NULL THEN
      v_new_data:=COALESCE(v_existing.data,'{}'::jsonb)||jsonb_build_object('extra_notes',coalesce(v_existing.data->'extra_notes','[]'::jsonb)||to_jsonb(v_note));
      IF octet_length(v_new_data::text)>(SELECT (r->>'base_limit')::bigint FROM jsonb_array_elements(v_policy->'rules') r WHERE r->>'rule_key'='cleaning.report.bytes') THEN
        RETURN jsonb_build_object('code',429,'message','Report note capacity is limited'); END IF;
      UPDATE public.cleaning_reports SET data=v_new_data WHERE id=v_existing.id;
    END IF;
    RETURN jsonb_build_object('code',200,'data',jsonb_build_object('duplicate',true,'id',v_existing.id));
  END IF;

  INSERT INTO public.cleaning_reports (occasion, place, problem_type, note, created_by)
  VALUES (v_occasion, place_id, problem_type, v_note, v_user)
  RETURNING * INTO v_report;

  -- Notify the crew (uuid array of is_cleaning_crew users on this occasion),
  -- excluding anyone who muted cleaning notifications for themselves
  -- (occasion_users.data.cleaning_notifications_off).
  SELECT jsonb_agg("user"::text) INTO v_crew
  FROM public.occasion_users
  WHERE occasion = v_occasion
    AND is_cleaning_crew = true
    AND COALESCE((data->>'cleaning_notifications_off')::boolean, false) = false;

  IF v_crew IS NOT NULL AND jsonb_array_length(v_crew) > 0 THEN
    -- organization comes straight from the occasion row (occasions.organization
    -- is NOT NULL) — no magic fallback needed.
    SELECT organization INTO v_organization FROM public.occasions WHERE id = v_occasion;

    BEGIN
      PERFORM public.charge_notification_intent_v1(v_occasion,v_user,v_crew,v_place.title || ' - ' || v_type_label,COALESCE(v_note,v_type_label));
    INSERT INTO public.log_notifications (occasion, organization, user_id, "to", heading, content, data, abuse_admitted_at)
    VALUES (
      v_occasion,
      v_organization,
      v_user,
      v_crew,
      v_place.title || ' — ' || v_type_label,
      COALESCE(v_note, v_type_label),
      jsonb_build_object('path', 'cleaning'), statement_timestamp()
    ) RETURNING id INTO v_notification;
    PERFORM public.dispatch_log_notification_v1(v_notification);
    EXCEPTION WHEN SQLSTATE 'PT429' THEN v_notification_deferred:=true; END;
  END IF;

  RETURN jsonb_build_object(
    'code', 200,
    'data', jsonb_build_object('duplicate', false, 'id', v_report.id, 'notificationDeferred',v_notification_deferred)
  );
END;
$$;


-- Source: database/functions/eshop_orders/storno_order_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.storno_order_client_sync_v1(p_order bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path = public, extensions
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_before_users uuid[];
BEGIN
  SELECT o.occasion INTO v_occasion FROM eshop.orders o WHERE o.id=p_order;
  IF v_actor IS NULL OR v_occasion IS NULL
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'order',p_order)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.order.cancel',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM public.admit_order_mutation_v1(v_occasion,(SELECT count(*) FROM eshop.order_product_ticket WHERE "order"=p_order));
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
    FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  PERFORM public.update_order_and_tickets_to_storno_ws_internal_v1(p_order);
  RETURN public.complete_profile_inventory_membership_mutation_v1(
    p_command_id,v_occasion,'inventory.order.cancel',
    jsonb_build_array(jsonb_build_object('entityType','order','entityId',p_order,
      'operation','update','safeLabel','Order cancellation',
      'changedFields',jsonb_build_array('state','tickets','membership','allocations'))),
    v_before_users,jsonb_build_object('orderId',p_order));
END; $function$;

REVOKE ALL ON FUNCTION public.storno_order_client_sync_v1(bigint,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.storno_order_client_sync_v1(bigint,uuid) TO authenticated;


-- Source: database/functions/eshop_orders/storno_tickets_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.storno_tickets_client_sync_v1(
  p_tickets bigint[],p_command_id uuid
) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_before_users uuid[]; v_changed_orders bigint[]; v_cancelled jsonb; v_updated jsonb;
BEGIN
  IF cardinality(p_tickets)>(SELECT hard_cap FROM public.abuse_policy_rules WHERE rule_key='order.mutation.items') THEN RAISE SQLSTATE 'PT429' USING MESSAGE='abuse_limit_exceeded'; END IF;
  SELECT min(t.occasion) INTO v_occasion FROM eshop.tickets t
    WHERE t.id=ANY(p_tickets);
  IF v_actor IS NULL OR v_occasion IS NULL OR cardinality(p_tickets)=0
    OR (SELECT count(*) FROM eshop.tickets t
      WHERE t.id=ANY(p_tickets) AND t.occasion=v_occasion)
      <>cardinality(ARRAY(SELECT DISTINCT id FROM unnest(p_tickets) id))
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'tickets',p_tickets)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.tickets.cancel',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM public.admit_order_mutation_v1(v_occasion,cardinality(p_tickets));
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
    FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  PERFORM public.lock_order_capacity_scope_internal(ARRAY(SELECT DISTINCT "order" FROM eshop.order_product_ticket WHERE ticket=ANY(p_tickets)));
  -- Lock in the same order as the bulk mutation, then capture only actual changes.
  PERFORM o.id FROM eshop.orders o WHERE o.id IN (
    SELECT opt."order" FROM eshop.order_product_ticket opt
    JOIN eshop.tickets t ON t.id=opt.ticket
    WHERE t.id=ANY(p_tickets)) ORDER BY o.id FOR UPDATE;
  SELECT array_agg(DISTINCT opt."order") INTO v_changed_orders
    FROM eshop.order_product_ticket opt JOIN eshop.tickets t ON t.id=opt.ticket
    WHERE t.id=ANY(p_tickets) AND t.state IS DISTINCT FROM 'storno';
  PERFORM public.storno_tickets_bulk_internal_v1(p_tickets);
  SELECT coalesce(jsonb_agg(o.id ORDER BY o.id) FILTER(WHERE o.state='storno'),'[]'::jsonb),
    coalesce(jsonb_agg(jsonb_build_object('id',o.id,'email',o.data->>'email') ORDER BY o.id)
      FILTER(WHERE o.state IS DISTINCT FROM 'storno'),'[]'::jsonb)
    INTO v_cancelled,v_updated FROM eshop.orders o WHERE o.id=ANY(v_changed_orders);
  RETURN public.complete_profile_inventory_membership_mutation_v1(
    p_command_id,v_occasion,'inventory.tickets.cancel',
    jsonb_build_array(jsonb_build_object('entityType','ticket','entityId',NULL,
      'operation','update','safeLabel','Ticket cancellation',
      'changedFields',jsonb_build_array('state','membership','allocations'))),
    v_before_users,jsonb_build_object('ticketIds',to_jsonb(p_tickets),
      'cancelledOrderIds',v_cancelled,'updatedOrders',v_updated));
END; $$;
REVOKE ALL ON FUNCTION public.storno_tickets_client_sync_v1(bigint[],uuid)
  FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.storno_tickets_client_sync_v1(bigint[],uuid)
  TO authenticated;


-- Source: database/functions/eshop_orders/delete_order_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.delete_order_client_sync_v1(
  p_order bigint,p_command_id uuid
) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_unit bigint;
  v_begin jsonb; v_hash text; v_removed_users uuid[]; v_remaining_users uuid[];
  v_public text[]:='{}'; v_dirty jsonb:='[]'::jsonb;
BEGIN
  SELECT o.occasion,oc.unit INTO v_occasion,v_unit FROM eshop.orders o
    JOIN public.occasions oc ON oc.id=o.occasion WHERE o.id=p_order;
  IF v_actor IS NULL OR v_occasion IS NULL
    OR NOT (public.get_is_manager_on_unit(v_unit)
      OR public.get_is_editor_on_unit(v_unit)) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager or editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'order',p_order)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.order.delete',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM public.admit_order_mutation_v1(v_occasion,(SELECT count(*) FROM eshop.order_product_ticket WHERE "order"=p_order));
  -- Serialize membership cleanup with the existing profile/group imports.
  PERFORM pg_catalog.pg_advisory_xact_lock(v_occasion);
  PERFORM 1 FROM public.user_group_info g WHERE g.occasion=v_occasion
    ORDER BY g.id FOR UPDATE;
  SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_removed_users
  FROM eshop.order_product_ticket opt JOIN public.occasion_users ou
    ON ou.ticket=opt.ticket AND ou.occasion=v_occasion
  WHERE opt."order"=p_order;
  PERFORM public.delete_order_internal_v1(p_order);
  DELETE FROM public.client_sync_private_scopes s WHERE s.occasion=v_occasion
    AND s.user_id=ANY(v_removed_users);
  DELETE FROM public.client_aggregate_versions v
    WHERE v.aggregate_type='occasion_user' AND v.scope_type='occasion'
      AND v.scope_id=v_occasion AND v.aggregate_id=ANY(
        ARRAY(SELECT id::text FROM unnest(v_removed_users) id));
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_remaining_users
    FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  IF cardinality(v_removed_users)>0 THEN
    v_public:=ARRAY['live_public'];
    SELECT COALESCE(jsonb_agg(jsonb_build_object('component','live_public',
      'entityId',e.id)),'[]'::jsonb) INTO v_dirty
      FROM public.events e WHERE e.occasion=v_occasion;
  END IF;
  RETURN public.complete_private_profile_mutation_v1(p_command_id,v_occasion,
    'inventory.order.delete',jsonb_build_array(jsonb_build_object(
      'entityType','order','entityId',p_order,'operation','delete',
      'safeLabel','Order','changedFields',jsonb_build_array(
        'tickets','membership','allocations'))),v_remaining_users,v_public,v_dirty,
    jsonb_build_object('orderId',p_order,'removedUsers',cardinality(v_removed_users)));
END; $$;
REVOKE ALL ON FUNCTION public.delete_order_client_sync_v1(bigint,uuid)
  FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.delete_order_client_sync_v1(bigint,uuid)
  TO authenticated;



-- Source: database/functions/abuse/legacy_order_facades.sql
-- The unversioned historical JSON facades previously retained an old separate
-- cancellation implementation. Keep their result shape, route through the same
-- authorized receipt-bearing domain command as the current _221 facade.
CREATE OR REPLACE FUNCTION public.update_order_and_tickets_to_storno(order_id bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.storno_order_client_sync_v1(order_id,extensions.gen_random_uuid());
 RETURN jsonb_build_object('code',200,'message','Order and all associated tickets successfully cancelled',
  'order_id',order_id,'tickets_updated',(SELECT jsonb_agg(ticket) FROM eshop.order_product_ticket WHERE "order"=order_id));
END $$;
CREATE OR REPLACE FUNCTION public.update_order_and_tickets_to_storno_ws(order_id bigint)
RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT public.update_order_and_tickets_to_storno(order_id);
$$;
REVOKE ALL ON FUNCTION public.update_order_and_tickets_to_storno(bigint),public.update_order_and_tickets_to_storno_ws(bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.update_order_and_tickets_to_storno(bigint),public.update_order_and_tickets_to_storno_ws(bigint) TO authenticated;
REVOKE ALL ON FUNCTION public.storno_tickets_bulk_internal_v1(bigint[]),public.update_order_and_tickets_to_storno_ws_internal_v1(bigint),public.delete_order_internal_v1(bigint) FROM service_role;


-- Source: database/functions/users/reception_qr_login.sql
-- Compatibility parameter is deliberately ignored: limits belong to the catalog.
CREATE OR REPLACE FUNCTION public.reception_rate_limit_v1(p_operation text,p_limit integer DEFAULT 30)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF auth.uid() IS NULL OR p_operation IS NULL OR p_operation NOT IN ('create','issue','revoke','cancel') THEN RETURN false; END IF;
 RETURN public.abuse_charge_v1(public.abuse_effective_rules_v1('reception.'||p_operation,NULL,NULL),jsonb_build_object('actor',auth.uid()),'{}',true);
END $$;

CREATE OR REPLACE FUNCTION public.get_reception_registration_options_v1(p_occasion bigint)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_services jsonb;
BEGIN
  IF NOT public.get_can_use_reception(p_occasion) THEN
    RETURN jsonb_build_object('code',403,'message','reception_unavailable');
  END IF;
  SELECT COALESCE(o.services,'{}'::jsonb) INTO v_services FROM public.occasions o WHERE o.id=p_occasion;
  RETURN jsonb_build_object('code',200,'groups',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',g.id,'title',g.title) ORDER BY g.title)
    FROM public.user_group_info g WHERE g.occasion=p_occasion AND g.type IS NULL),'[]'::jsonb),
    'accommodations',COALESCE((SELECT jsonb_agg(jsonb_build_object('code',x.item->>'code','title',x.item->>'title','placeTitle',p.title) ORDER BY x.ordinality)
      FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_services->'accommodation')='array' THEN v_services->'accommodation' ELSE '[]'::jsonb END)
      WITH ORDINALITY x(item,ordinality) LEFT JOIN public.places p ON p.occasion=p_occasion AND p.id=CASE WHEN x.item->>'reference' ~ '^[0-9]+$' THEN (x.item->>'reference')::bigint END),'[]'::jsonb));
END $$;

CREATE OR REPLACE FUNCTION public.create_reception_user_v1(p_occasion bigint,p_command_id uuid,p_profile jsonb,p_group_id bigint DEFAULT NULL,p_accommodation_code text DEFAULT NULL,p_confirm_same_name boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_actor uuid:=auth.uid(); v_org bigint; v_user uuid; v_hash text; v_existing public.reception_registrations%rowtype;
  v_name text:=btrim(p_profile->>'name'); v_surname text:=btrim(p_profile->>'surname'); v_email text:=lower(btrim(p_profile->>'email'));
  v_sex text:=p_profile->>'sex'; v_matches jsonb; v_services jsonb:='{}'::jsonb; v_catalog jsonb;
BEGIN
  IF NOT public.get_can_use_reception(p_occasion) THEN RETURN jsonb_build_object('code',403,'message','reception_unavailable'); END IF;
  IF NOT public.reception_rate_limit_v1('create') THEN RETURN jsonb_build_object('code',429,'message','rate_limited'); END IF;
  IF p_profile IS NULL OR jsonb_typeof(p_profile)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_profile) k WHERE k NOT IN('name','surname','email','sex','phone','birthDate'))
  THEN RETURN jsonb_build_object('code',400,'message','invalid_profile_fields'); END IF;
  IF COALESCE(v_name,'')='' OR COALESCE(v_surname,'')='' OR COALESCE(v_email,'')='' OR position('@' IN v_email)<=1 OR v_sex NOT IN('male','female','unspecified')
  THEN RETURN jsonb_build_object('code',400,'message','required_profile_fields'); END IF;
  v_hash:=encode(digest(jsonb_build_object('profile',p_profile,'group',p_group_id,'accommodation',p_accommodation_code)::text,'sha256'),'hex');
  SELECT * INTO v_existing FROM public.reception_registrations WHERE occasion=p_occasion AND created_by=v_actor AND command_id=p_command_id;
  IF FOUND THEN
    IF v_existing.request_hash<>v_hash THEN RETURN jsonb_build_object('code',409,'message','command_conflict'); END IF;
    SELECT ui.email_readonly INTO v_email FROM public.user_info ui WHERE ui.id=v_existing."user";
    RETURN jsonb_build_object('code',200,'userId',v_existing."user",'email',v_email,'replayed',true);
  END IF;
  SELECT o.organization,COALESCE(o.services,'{}'::jsonb) INTO v_org,v_catalog FROM public.occasions o WHERE o.id=p_occasion FOR SHARE;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('reception-email:'||v_org::text||':'||v_email,0));
  SELECT ui.id INTO v_user
  FROM public.user_info ui
  WHERE ui.organization=v_org AND lower(btrim(ui.email_readonly))=v_email;
  IF v_user IS NOT NULL THEN
    IF (public.get_is_admin_on_occasion(p_occasion)
        OR public.get_is_manager_on_occasion(p_occasion))
      AND EXISTS(SELECT 1 FROM public.occasion_users ou
        WHERE ou.occasion=p_occasion AND ou."user"=v_user) THEN
      RETURN jsonb_build_object('code',200,'userId',v_user,'email',v_email,
        'existing',true,'replayed',false);
    END IF;
    RETURN jsonb_build_object('code',409,'message','email_already_exists');
  END IF;
  SELECT COALESCE(jsonb_agg(candidate),'[]'::jsonb) INTO v_matches FROM (
    SELECT jsonb_build_object('name',ui.name,'surname',ui.surname,'sex',ui.sex,
      'birthYear',CASE WHEN ui.birth_date IS NULL THEN NULL ELSE extract(year FROM ui.birth_date)::int END,
      'email',CASE WHEN position('@' IN ui.email_readonly)>2 THEN left(ui.email_readonly,1)||'***@'||split_part(ui.email_readonly,'@',2) ELSE '***' END,
      'onOccasion',EXISTS(SELECT 1 FROM public.occasion_users ou WHERE ou.occasion=p_occasion AND ou."user"=ui.id)) candidate
    FROM public.user_info ui WHERE ui.organization=v_org AND public.f_unaccent(btrim(ui.name))=public.f_unaccent(v_name)
      AND public.f_unaccent(btrim(ui.surname))=public.f_unaccent(v_surname) ORDER BY ui.created_at NULLS LAST LIMIT 10) q;
  IF jsonb_array_length(v_matches)>0 AND NOT p_confirm_same_name THEN RETURN jsonb_build_object('code',409,'message','same_name_confirmation_required','candidates',v_matches); END IF;
  IF p_group_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.user_group_info g WHERE g.id=p_group_id AND g.occasion=p_occasion AND g.type IS NULL FOR SHARE)
  THEN RETURN jsonb_build_object('code',400,'message','invalid_group'); END IF;
  IF p_accommodation_code IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_catalog->'accommodation')='array' THEN v_catalog->'accommodation' ELSE '[]'::jsonb END) x WHERE x->>'code'=p_accommodation_code)
  THEN RETURN jsonb_build_object('code',400,'message','invalid_accommodation'); END IF;
  v_user:=public.create_user_in_organization_with_data_pure(v_org,v_email,v_email,encode(gen_random_bytes(32),'hex'),p_profile-'email');
  IF p_accommodation_code IS NOT NULL THEN v_services:=jsonb_build_object('accommodation',jsonb_build_object(p_accommodation_code,'paid')); END IF;
  INSERT INTO public.occasion_users(occasion,"user",data,services) VALUES(p_occasion,v_user,p_profile,v_services);
  IF p_group_id IS NOT NULL THEN INSERT INTO public.user_groups("user","group",is_admin) VALUES(v_user,p_group_id,false); END IF;
  INSERT INTO public.reception_registrations(occasion,"user",created_by,command_id,request_hash) VALUES(p_occasion,v_user,v_actor,p_command_id,v_hash);
  RETURN jsonb_build_object('code',200,'userId',v_user,'email',v_email,'replayed',false);
EXCEPTION WHEN unique_violation THEN RETURN jsonb_build_object('code',409,'message','email_or_command_conflict');
END $$;

CREATE OR REPLACE FUNCTION public.issue_reception_login_qr_v1(p_occasion bigint,p_user uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_token text; v_hash text; v_actor uuid:=auth.uid();
  v_manual text; v_manual_hash text; v_manual_bytes bytea; v_alphabet constant text:='23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
BEGIN
  IF NOT public.get_can_use_reception(p_occasion) THEN RETURN jsonb_build_object('code',403,'message','reception_unavailable'); END IF;
  IF NOT public.reception_rate_limit_v1('issue') THEN RETURN jsonb_build_object('code',429,'message','rate_limited'); END IF;
  IF NOT EXISTS(SELECT 1 FROM public.occasion_users ou WHERE ou.occasion=p_occasion AND ou."user"=p_user)
    OR NOT (public.get_is_admin_on_occasion(p_occasion)
      OR public.get_is_manager_on_occasion(p_occasion) OR EXISTS(
      SELECT 1 FROM public.reception_registrations r
      WHERE r.occasion=p_occasion AND r."user"=p_user AND r.status='active'
        AND r.created_by=v_actor AND r.created_at>now()-interval '30 minutes')) THEN
    RETURN jsonb_build_object('code',403,'message','registration_unavailable'); END IF;
  v_token:=translate(encode(gen_random_bytes(32),'base64'),E'+/=\n','-_'); v_hash:=encode(digest(v_token,'sha256'),'hex');
  v_manual_bytes:=gen_random_bytes(8);
  SELECT string_agg(substr(v_alphabet,(get_byte(v_manual_bytes,i)%32)+1,1),'') INTO v_manual FROM generate_series(0,7) i;
  v_manual_hash:=encode(digest(v_manual,'sha256'),'hex');
  INSERT INTO public.user_login_qr_credentials(occasion,"user",token_hash,manual_token_hash,manual_expires_at,created_by)
  VALUES(p_occasion,p_user,v_hash,v_manual_hash,now()+interval '30 minutes',v_actor)
  ON CONFLICT(occasion,"user") DO UPDATE SET token_hash=excluded.token_hash,manual_token_hash=excluded.manual_token_hash,
    manual_expires_at=excluded.manual_expires_at,created_by=excluded.created_by,rotated_at=now(),revoked_at=NULL,last_used_at=NULL,use_count=0;
  RETURN jsonb_build_object('code',200,'payload','festapp-login:v1:'||p_occasion::text||':'||v_token,
    'manualCode',left(v_manual,4)||'-'||right(v_manual,4));
END $$;

CREATE OR REPLACE FUNCTION public.get_reception_occasion_users_v1(p_occasion bigint,p_query text DEFAULT '')
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
SELECT CASE
  WHEN public.get_can_use_reception(p_occasion)
    AND (public.get_is_admin_on_occasion(p_occasion)
      OR public.get_is_manager_on_occasion(p_occasion))
  THEN COALESCE(jsonb_agg(jsonb_build_object(
    'userId',q.id,'name',q.name,'surname',q.surname,'email',q.email_readonly
  ) ORDER BY q.surname,q.name,q.email_readonly),'[]'::jsonb)
  ELSE '[]'::jsonb
END
FROM (
  SELECT ui.id,ui.name,ui.surname,ui.email_readonly
  FROM public.occasion_users ou
  JOIN public.user_info ui ON ui.id=ou."user"
  WHERE ou.occasion=p_occasion
    AND (COALESCE(btrim(p_query),'')=''
      OR public.f_unaccent(COALESCE(ui.name,'')||' '||COALESCE(ui.surname,'')||' '||COALESCE(ui.email_readonly,''))
        ILIKE '%'||public.f_unaccent(btrim(left(p_query,100)))||'%')
  ORDER BY ui.surname,ui.name,ui.email_readonly
  LIMIT 50
) q; $$;

CREATE OR REPLACE FUNCTION public.resolve_reception_login_qr_v1(p_occasion bigint,p_token_hash text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_user uuid; v_email text;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'not_authorized'; END IF;
  SELECT c."user",(o.organization::text||'+'||au.email_readonly) INTO v_user,v_email
  FROM public.user_login_qr_credentials c JOIN public.occasion_users ou ON (ou.occasion,ou."user")=(c.occasion,c."user")
  JOIN public.user_info au ON au.id=c."user" JOIN public.occasions o ON o.id=c.occasion
  WHERE c.occasion=p_occasion
    AND (c.token_hash=p_token_hash OR (c.manual_token_hash=p_token_hash AND c.manual_expires_at>now()))
    AND c.revoked_at IS NULL
    AND jsonb_path_exists(COALESCE(o.features,'[]'::jsonb),'$[*] ? (@.code == "reception" && @.is_enabled == true)') FOR UPDATE OF c;
  IF v_user IS NULL THEN RETURN NULL; END IF;
  RETURN jsonb_build_object('userId',v_user,'authEmail',v_email);
END $$;

CREATE OR REPLACE FUNCTION public.revoke_reception_login_qr_v1(p_occasion bigint,p_user uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_actor uuid:=auth.uid();
BEGIN
  IF NOT public.get_can_use_reception(p_occasion) THEN
    RETURN jsonb_build_object('code',403,'message','reception_unavailable');
  END IF;
  IF NOT public.reception_rate_limit_v1('revoke') THEN
    RETURN jsonb_build_object('code',429,'message','rate_limited');
  END IF;
  IF NOT EXISTS(
    SELECT 1 FROM public.reception_registrations r
    WHERE r.occasion=p_occasion AND r."user"=p_user AND r.status='active'
      AND ((r.created_by=v_actor AND r.created_at>now()-interval '30 minutes')
        OR public.get_is_manager_on_occasion(p_occasion)
        OR public.get_is_admin_on_occasion(p_occasion))
  ) THEN
    RETURN jsonb_build_object('code',403,'message','registration_unavailable');
  END IF;
  UPDATE public.user_login_qr_credentials
  SET revoked_at=now()
  WHERE occasion=p_occasion AND "user"=p_user AND revoked_at IS NULL;
  RETURN jsonb_build_object('code',200,'status','revoked');
END $$;

CREATE OR REPLACE FUNCTION public.mark_reception_login_qr_used_v1(p_occasion bigint,p_token_hash text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'not_authorized'; END IF;
  UPDATE public.user_login_qr_credentials c SET
    last_used_at=now(),
    use_count=use_count+1,
    manual_token_hash=CASE WHEN c.manual_token_hash=p_token_hash THEN NULL ELSE c.manual_token_hash END,
    manual_expires_at=CASE WHEN c.manual_token_hash=p_token_hash THEN NULL ELSE c.manual_expires_at END
  FROM public.occasion_users ou,public.occasions o
  WHERE c.occasion=p_occasion
    AND (c.token_hash=p_token_hash OR (c.manual_token_hash=p_token_hash AND c.manual_expires_at>now()))
    AND c.revoked_at IS NULL
    AND (ou.occasion,ou."user")=(c.occasion,c."user") AND o.id=c.occasion
    AND jsonb_path_exists(COALESCE(o.features,'[]'::jsonb),'$[*] ? (@.code == "reception" && @.is_enabled == true)');
END $$;

CREATE OR REPLACE FUNCTION public.cancel_reception_registration_v1(p_occasion bigint,p_user uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE v_r public.reception_registrations%rowtype; v_actor uuid:=auth.uid();
BEGIN
  SELECT * INTO v_r FROM public.reception_registrations WHERE occasion=p_occasion AND "user"=p_user FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('code',404,'message','registration_unavailable'); END IF;
  IF NOT public.get_can_use_reception(p_occasion) OR NOT (public.get_is_manager_on_occasion(p_occasion) OR public.get_is_admin_on_occasion(p_occasion) OR (v_r.created_by=v_actor AND (v_r.status='cancelled' OR v_r.created_at>now()-interval '30 minutes'))) THEN
    RETURN jsonb_build_object('code',403,'message','registration_unavailable'); END IF;
  IF v_r.status='cancelled' THEN RETURN jsonb_build_object('code',200,'status',CASE WHEN v_r.auth_revoked_at IS NULL THEN 'domain_blocked_auth_revocation_pending' ELSE 'cancelled' END,'targetUser',p_user); END IF;
  IF NOT public.reception_rate_limit_v1('cancel') THEN RETURN jsonb_build_object('code',429,'message','rate_limited'); END IF;
  UPDATE public.reception_registrations SET status='cancelled',cancelled_by=v_actor,cancelled_at=now() WHERE occasion=p_occasion AND "user"=p_user;
  PERFORM public.delete_occasion_user(p_user,p_occasion);
  RETURN jsonb_build_object('code',200,'status','domain_blocked_auth_revocation_pending','targetUser',p_user);
END $$;

CREATE OR REPLACE FUNCTION public.mark_reception_auth_revoked_v1(p_occasion bigint,p_user uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'not_authorized'; END IF;
UPDATE public.reception_registrations SET auth_revoked_at=now() WHERE occasion=p_occasion AND "user"=p_user AND status='cancelled'; END $$;

CREATE OR REPLACE FUNCTION public.get_my_recent_reception_registrations_v1(p_occasion bigint)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
SELECT CASE WHEN public.get_can_use_reception(p_occasion) THEN COALESCE(jsonb_agg(jsonb_build_object('userId',r."user",'name',ui.name,'surname',ui.surname,'email',ui.email_readonly,'createdAt',r.created_at,'qrUsed',c.last_used_at IS NOT NULL) ORDER BY r.created_at DESC),'[]'::jsonb) ELSE '[]'::jsonb END
FROM public.reception_registrations r JOIN public.user_info ui ON ui.id=r."user" LEFT JOIN public.user_login_qr_credentials c ON (c.occasion,c."user")=(r.occasion,r."user")
WHERE r.occasion=p_occasion AND r.created_by=auth.uid() AND r.status='active' AND r.created_at>now()-interval '30 minutes'; $$;

REVOKE ALL ON FUNCTION public.reception_rate_limit_v1(text,integer),public.get_reception_occasion_users_v1(bigint,text),public.resolve_reception_login_qr_v1(bigint,text),public.mark_reception_login_qr_used_v1(bigint,text),public.mark_reception_auth_revoked_v1(bigint,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.resolve_reception_login_qr_v1(bigint,text),public.mark_reception_login_qr_used_v1(bigint,text),public.mark_reception_auth_revoked_v1(bigint,uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.get_reception_registration_options_v1(bigint),public.create_reception_user_v1(bigint,uuid,jsonb,bigint,text,boolean),public.issue_reception_login_qr_v1(bigint,uuid),public.get_reception_occasion_users_v1(bigint,text),public.revoke_reception_login_qr_v1(bigint,uuid),public.cancel_reception_registration_v1(bigint,uuid),public.get_my_recent_reception_registrations_v1(bigint) TO authenticated,service_role;


-- Source: database/functions/abuse/reception.sql
-- Adoption uses stable actor/operation identity, never a new policy revision.
INSERT INTO public.abuse_budget_usage(rule_key,scope_id,bucket_at,amount,expires_at)
SELECT 'reception.'||operation||'.actor',actor::text,bucket,count,bucket+interval '2 minutes'
FROM public.reception_rate_limits WHERE bucket>now()-interval '1 minute' AND count>0 AND operation IN ('create','issue','revoke');
DROP TABLE public.reception_rate_limits;
-- Preserve report work already consumed before replacing the history counter.
INSERT INTO public.abuse_budget_usage(rule_key,scope_id,bucket_at,amount,expires_at)
SELECT 'cleaning.report.actor',created_by::text,
 to_timestamp(floor(extract(epoch FROM created_at)/300)*300),count(*),
 to_timestamp(floor(extract(epoch FROM created_at)/300)*300)+interval '20 minutes'
FROM public.cleaning_reports WHERE created_by IS NOT NULL AND created_at>now()-interval '15 minutes'
GROUP BY created_by,to_timestamp(floor(extract(epoch FROM created_at)/300)*300);


-- Source: database/functions/eshop_orders/scan_ticket.sql
CREATE OR REPLACE FUNCTION public.scan_ticket(scanned_id TEXT, scanned_code TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    ticket_row RECORD;
    order_json JSONB;
    products_json JSONB;
    spot_json JSONB;
    groups_json JSONB; -- New variable for groups
    order_id BIGINT;
    occasion_id BIGINT;
    hide_price BOOLEAN := FALSE;
    target_user_id UUID; -- New variable to store the resolved User ID
    expected_scan_code TEXT;
    is_uuid BOOLEAN;
    -- Deposit info variables
    v_deposit_amount NUMERIC;
    v_paid NUMERIC;
    v_amount NUMERIC;
    v_deposit_deadline_days INT;
    v_deposit_deadline TEXT;
    v_occ_start_time TIMESTAMPTZ;
    v_occ_features JSONB;
    v_deposit_feature JSONB;
    v_deposit_info JSONB;
BEGIN
    IF NOT public.check_scan_attempt_budget_v1((SELECT occasion FROM eshop.tickets WHERE ticket_symbol=scanned_id LIMIT 1)) THEN
        RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded');
    END IF;
    -----------------------------------------------------
    -- 1. Attempt to find ticket by Ticket Symbol
    -----------------------------------------------------
    SELECT *
      INTO ticket_row
    FROM eshop.tickets
    WHERE ticket_symbol = scanned_id
    LIMIT 1;

    -----------------------------------------------------
    -- 1.a. Fallback: Scan by User ID if Ticket Symbol not found
    -----------------------------------------------------
    IF ticket_row IS NULL THEN
        -- Check if the scanned_id is a valid UUID format
        is_uuid := scanned_id ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';

        IF is_uuid THEN
            -- If scanned by UUID, we know the user immediately
            target_user_id := scanned_id::UUID;

            SELECT t.*
              INTO ticket_row
            FROM public.occasion_users ou
            JOIN public.occasions o ON ou.occasion = o.id
            JOIN public.occasions_hidden oh ON o.occasion_hidden = oh.id
            JOIN eshop.tickets t ON ou.ticket = t.id
            WHERE ou.user = target_user_id
              AND oh.secret = scanned_code
            LIMIT 1;
        END IF;
    END IF;

    -----------------------------------------------------
    -- 1.b. Final Check if Ticket is still missing
    -----------------------------------------------------
    IF ticket_row IS NULL OR ticket_row.state='waitlisted' OR ticket_row.ticket_symbol IS NULL THEN
        PERFORM public.admit_scan_access_v1(NULL,false);
        RETURN jsonb_build_object('code', 404, 'message', 'Ticket or User with valid ticket not found');
    END IF;

    -----------------------------------------------------
    -- 2. Retrieve the associated order ID
    -----------------------------------------------------
    SELECT opt."order" INTO order_id
    FROM eshop.order_product_ticket opt
    WHERE opt.ticket = ticket_row.id
    LIMIT 1;

    IF order_id IS NULL THEN
        PERFORM public.admit_scan_access_v1(NULL,false);
        RETURN jsonb_build_object('code', 404, 'message', 'Order for ticket not found');
    END IF;

    -----------------------------------------------------
    -- 3. Retrieve the occasion ID from the order
    -----------------------------------------------------
    SELECT o.occasion, occ.link = 'r48vetrkovice2026'
      INTO occasion_id, hide_price
    FROM eshop.orders o
    JOIN public.occasions occ ON occ.id = o.occasion
    WHERE o.id = order_id
    LIMIT 1;

    PERFORM public.check_occasion_writable(occasion_id);
    IF occasion_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Occasion for order not found');
    END IF;

    -----------------------------------------------------
    -- 3.b. Resolve User ID if not already found via UUID scan
    -----------------------------------------------------
    -- If we found the ticket via Symbol (Step 1), we need to find who holds it
    IF target_user_id IS NULL THEN
        SELECT "user" INTO target_user_id
        FROM public.occasion_users
        WHERE ticket = ticket_row.id
          AND occasion = occasion_id
        LIMIT 1;
    END IF;

    -----------------------------------------------------
    -- 4. Retrieve the expected scan_code
    -----------------------------------------------------
    SELECT oh.secret
      INTO expected_scan_code
    FROM public.occasions_hidden oh
    JOIN public.occasions o ON o.occasion_hidden = oh.id
    WHERE o.id = occasion_id
    LIMIT 1;

    IF expected_scan_code IS NULL THEN
        PERFORM public.admit_scan_access_v1(occasion_id,false);
        RETURN jsonb_build_object('code', 400, 'message', 'Scan code not defined for this occasion');
    END IF;

    -----------------------------------------------------
    -- 5. Validate the scanned_code
    -----------------------------------------------------
    IF scanned_code IS DISTINCT FROM expected_scan_code THEN
        PERFORM public.admit_scan_access_v1(occasion_id,false);
        RETURN jsonb_build_object('code', 401, 'message', 'Scan code is not correct');
    END IF;

    -----------------------------------------------------
    -- 6. Fetch order, products, spot, AND GROUPS
    -----------------------------------------------------

    IF NOT public.admit_scan_access_v1(occasion_id,true) THEN
        RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded');
    END IF;

    -- A. Fetch Order
    SELECT CASE
             WHEN hide_price THEN
               (to_jsonb(o) - 'price') || jsonb_build_object(
                 'data',
                 CASE
                   WHEN jsonb_typeof(o.data->'tickets') = 'array' THEN
                     jsonb_set(
                       o.data,
                       '{tickets}',
                       COALESCE(
                         (
                           SELECT jsonb_agg(
                             CASE
                               WHEN jsonb_typeof(ticket->'products') = 'array' THEN
                                 jsonb_set(
                                   ticket,
                                   '{products}',
                                   COALESCE(
                                     (
                                       SELECT jsonb_agg(product - 'price')
                                       FROM jsonb_array_elements(ticket->'products') AS product
                                     ),
                                     '[]'::jsonb
                                   ),
                                   FALSE
                                 )
                               ELSE ticket
                             END
                           )
                           FROM jsonb_array_elements(o.data->'tickets') AS ticket
                         ),
                         '[]'::jsonb
                       ),
                       FALSE
                     )
                   ELSE o.data
                 END
               )
             ELSE to_jsonb(o)
           END
      INTO order_json
    FROM eshop.orders o
    WHERE o.id = order_id;

    -- B. Fetch Products
    SELECT jsonb_agg(
             CASE
               WHEN hide_price THEN
                 jsonb_build_object(
                   'id', p.id,
                   'title', p.title,
                   'order', p."order",
                   'description', p.description,
                   'currency_code', p.currency_code
                 )
               ELSE
                 jsonb_build_object(
                   'id', p.id,
                   'title', p.title,
                   'price', p.price,
                   'order', p."order",
                   'description', p.description,
                   'currency_code', p.currency_code
                 )
             END
           )
      INTO products_json
    FROM eshop.products p
    WHERE p.id IN (
        SELECT opt.product
          FROM eshop.order_product_ticket opt
         WHERE opt.ticket = ticket_row.id
    );

    -- C. Fetch Spot
    SELECT row_to_json(s) INTO spot_json
    FROM eshop.spots s
    WHERE s.order_product_ticket IN (
        SELECT opt.id
          FROM eshop.order_product_ticket opt
         WHERE opt.ticket = ticket_row.id
    )
    LIMIT 1;

    -- D. Fetch User Groups (New Logic)
    IF target_user_id IS NOT NULL THEN
        -- We construct a JSON object compatible with UserGroupInfoModel
        -- We join user_groups -> user_group_info -> places to get full context
        SELECT jsonb_agg(
                 to_jsonb(ugi) ||
                 jsonb_build_object(
                    'place_object', row_to_json(p)
                 )
               )
        INTO groups_json
        FROM public.user_groups ug
        JOIN public.user_group_info ugi ON ug."group" = ugi.id
        LEFT JOIN public.places p ON ugi.place = p.id
        WHERE ug."user" = target_user_id
          AND ugi.occasion = occasion_id;
    END IF;

    -----------------------------------------------------
    -- 6E. Fetch deposit info for deposit orders
    -----------------------------------------------------
    SELECT pi.deposit_amount, pi.paid, pi.amount
    INTO v_deposit_amount, v_paid, v_amount
    FROM eshop.payment_info pi
    JOIN eshop.orders o ON o.payment_info = pi.id
    WHERE o.id = order_id;

    IF v_deposit_amount IS NOT NULL THEN
        -- Get occasion features and start_time for deposit deadline
        SELECT occ.features, occ.start_time
        INTO v_occ_features, v_occ_start_time
        FROM public.occasions occ
        WHERE occ.id = occasion_id;

        -- Read deposit deadline from deposit feature in features JSONB
        SELECT elem INTO v_deposit_feature
        FROM jsonb_array_elements(v_occ_features) elem
        WHERE elem->>'code' = 'deposit';

        v_deposit_deadline_days := (v_deposit_feature->>'deposit_deadline_days')::int;
        v_deposit_deadline := v_deposit_feature->>'deposit_deadline';

        v_deposit_info := jsonb_build_object(
            'remaining_amount', GREATEST(0, COALESCE(v_amount, 0) - COALESCE(v_paid, 0)),
            'is_fully_paid', COALESCE(v_paid, 0) >= COALESCE(v_amount, 0),
            'deadline_type', CASE
                WHEN v_deposit_deadline = 'on_site' THEN 'on_site'
                WHEN v_deposit_deadline_days IS NOT NULL THEN 'date'
                ELSE NULL
            END,
            'deadline_date', CASE
                WHEN v_deposit_deadline_days IS NOT NULL AND v_deposit_deadline IS DISTINCT FROM 'on_site'
                THEN (v_occ_start_time - make_interval(days => v_deposit_deadline_days))::text
                ELSE NULL
            END,
            'deposit_amount', v_deposit_amount,
            'total_amount', v_amount,
            'paid_amount', COALESCE(v_paid, 0)
        );
    END IF;

    -----------------------------------------------------
    -- 7. Return the compiled JSONB response
    -----------------------------------------------------
    RETURN jsonb_build_object(
        'code', 200,
        'ticket', row_to_json(ticket_row),
        'order', order_json,
        'products', products_json,
        'spot', spot_json,
        'groups', COALESCE(groups_json, '[]'::jsonb),
        'deposit_info', v_deposit_info
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'code', 500,
            'message', 'An unexpected error occurred: ' || SQLERRM
        );
END;
$$;


-- Source: database/functions/eshop_orders/get_occasion_by_scan_code.sql
CREATE OR REPLACE FUNCTION public.get_occasion_by_scan_code(scan_code TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    found_occasion_record RECORD;
BEGIN
    IF NOT public.check_scan_attempt_budget_v1(NULL) THEN
        RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded');
    END IF;
    SELECT o.id, o.title, o.features
    INTO found_occasion_record
    FROM public.occasions o
    JOIN public.occasions_hidden oh ON o.occasion_hidden = oh.id
    WHERE oh.secret = scan_code
    LIMIT 1;

    IF found_occasion_record IS NULL THEN
        PERFORM public.admit_scan_access_v1(NULL,false);
        RETURN jsonb_build_object('code',401,'message','invalid_scan_code');
    END IF;

    IF NOT public.admit_scan_access_v1(found_occasion_record.id,true) THEN
        RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded');
    END IF;
    RETURN jsonb_build_object(
        'id', found_occasion_record.id,
        'title', found_occasion_record.title,
        'features', found_occasion_record.features
    );
END;
$$;


-- Source: database/functions/eshop_orders/get_all_tickets_for_scan.sql
CREATE OR REPLACE FUNCTION public.get_all_tickets_for_scan(scan_code text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    occasion_id_val bigint;
    result jsonb; policy jsonb; max_items bigint; max_bytes bigint; found_items bigint;
BEGIN
    IF NOT public.check_scan_attempt_budget_v1(NULL) THEN
        RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded');
    END IF;
    SELECT o.id
    INTO occasion_id_val
    FROM public.occasions o
    JOIN public.occasions_hidden oh ON o.occasion_hidden = oh.id
    WHERE oh.secret = scan_code
    LIMIT 1;

    IF occasion_id_val IS NULL THEN
         PERFORM public.admit_scan_access_v1(NULL,false);
         RETURN jsonb_build_object('code',401,'message','invalid_scan_code');
    END IF;

    IF NOT public.admit_scan_access_v1(occasion_id_val,true) THEN
        RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded');
    END IF;
    policy:=public.abuse_effective_rules_v1('scan.export',(SELECT unit FROM public.occasions WHERE id=occasion_id_val),(SELECT organization FROM public.occasions WHERE id=occasion_id_val));
    SELECT (r->>'base_limit')::bigint INTO max_items FROM jsonb_array_elements(policy->'rules') r WHERE r->>'rule_key'='scan.export.items';
    SELECT (r->>'base_limit')::bigint INTO max_bytes FROM jsonb_array_elements(policy->'rules') r WHERE r->>'rule_key'='scan.export.bytes';
    IF max_items IS NULL OR max_bytes IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
    SELECT count(*) INTO found_items FROM (SELECT id FROM eshop.tickets WHERE occasion=occasion_id_val LIMIT max_items+1) bounded;
    IF found_items>max_items THEN RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded'); END IF;

    SELECT jsonb_agg(
        jsonb_build_object(
            'id', t.id,
            'ticket_symbol', t.ticket_symbol,
            'state', t.state,
            'related_order', jsonb_build_object(
                 'data', t.data
            )
        ) 
    )
    INTO result
    FROM (
        SELECT DISTINCT ON (t.id) t.id, t.ticket_symbol, t.state, o.data
        FROM eshop.tickets t
        JOIN eshop.order_product_ticket opt ON t.id = opt.ticket
        JOIN eshop.orders o ON opt."order" = o.id
        WHERE o.occasion = occasion_id_val
          AND t.state IS DISTINCT FROM 'storno' AND t.state IS DISTINCT FROM 'waitlisted'
          AND t.ticket_symbol IS NOT NULL AND o.state IS DISTINCT FROM 'waitlisted'
        ORDER BY t.id
    ) t;

    IF octet_length(result::text)>max_bytes THEN RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded'); END IF;
    RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


-- Source: database/functions/eshop_orders/update_ticket_to_used.sql
CREATE OR REPLACE FUNCTION public.update_ticket_to_used(
    ticket_id bigint,
    scan_code text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    occasion_id bigint;
    current_state text;
    expected_scan_code text;
BEGIN
    IF NOT public.check_scan_attempt_budget_v1((SELECT occasion FROM eshop.tickets WHERE id=ticket_id)) THEN
        RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded');
    END IF;
    -- 1. Validate Ticket Existence
    IF NOT EXISTS (
        SELECT 1 FROM eshop.tickets WHERE id = ticket_id
    ) THEN
        PERFORM public.admit_scan_access_v1(NULL,false);
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Ticket not found.'
        );
    END IF;

    -- 2. Retrieve Associated Occasion ID AND Current State
    SELECT occasion, state
    INTO occasion_id, current_state
    FROM eshop.tickets
    WHERE id = ticket_id FOR UPDATE;

    -- Check if occasion_id is present (Integrity check)
    IF occasion_id IS NULL THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Occasion associated with ticket not found.'
        );
    END IF;

    -- 3. Retrieve Expected Scan Code from occasions_hidden via foreign key
    SELECT oh.secret
    INTO expected_scan_code
    FROM public.occasions_hidden oh
    JOIN public.occasions o ON o.occasion_hidden = oh.id
    WHERE o.id = occasion_id
    LIMIT 1;

    -- Check if scan_code is defined
    IF expected_scan_code IS NULL THEN
        PERFORM public.admit_scan_access_v1(occasion_id,false);
        RETURN jsonb_build_object(
            'code', 400,
            'message', 'Scan code not defined for occasion.'
        );
    END IF;

    -- 4. Validate Provided Scan Code
    IF scan_code IS DISTINCT FROM expected_scan_code THEN
        PERFORM public.admit_scan_access_v1(occasion_id,false);
        RETURN jsonb_build_object(
            'code', 401,
            'message', 'Scan code is not correct.'
        );
    END IF;

    IF NOT public.admit_scan_access_v1(occasion_id,true) THEN
        RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded');
    END IF;

    -- 2a. Validate Ticket State (New Check)
    IF current_state = 'used' THEN
        RETURN jsonb_build_object(
            'code', 409,
            'message', 'Ticket has already been used.'
        );
    ELSIF current_state = 'storno' THEN
        RETURN jsonb_build_object(
            'code', 409,
            'message', 'Ticket is cancelled (storno).'
        );
    END IF;

    PERFORM public.check_ticket_is_mutable(ticket_id);

    -- 5. Update Ticket State to 'used' AND update timestamp
    UPDATE eshop.tickets
    SET
        state = 'used',
        updated_at = now()
    WHERE id = ticket_id;

    -- 6. Return Success Message
    RETURN jsonb_build_object(
        'code', 200,
        'message', 'Ticket state updated to used successfully.'
    );

EXCEPTION
    WHEN OTHERS THEN
        -- Handle any unexpected exceptions
        RETURN jsonb_build_object(
            'code', 500,
            'message', 'An unexpected error occurred.',
            'detail', SQLERRM
        );
END;
$$;

-- Source: database/functions/eshop_orders/update_ticket_to_used_ws.sql
CREATE OR REPLACE FUNCTION public.update_ticket_to_used_ws(
    ticket_id bigint
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    occasion_id bigint;
    current_state text;
BEGIN
    -- 1. Retrieve the occasion ID and State from the ticket.
    -- If the ticket does not exist, this will raise a NO_DATA_FOUND exception (due to STRICT).
    SELECT occasion, state
    INTO STRICT occasion_id, current_state
    FROM eshop.tickets
    WHERE id = ticket_id FOR UPDATE;

    -- 2. Check if the current user has editor permissions for the occasion.
    -- This function will raise an exception if the user is not an editor.
    PERFORM public.check_is_editor_order_on_occasion(occasion_id);

    -- 1a. Check State Validity (New Check)
    IF current_state = 'used' THEN
        RAISE EXCEPTION 'Ticket % is already used.', ticket_id;
    ELSIF current_state = 'storno' THEN
        RAISE EXCEPTION 'Ticket % is cancelled (storno).', ticket_id;
    END IF;



    IF NOT public.admit_scan_access_v1(occasion_id,true) THEN
        RAISE SQLSTATE 'PT429' USING MESSAGE='abuse_limit_exceeded';
    END IF;
    PERFORM public.check_ticket_is_mutable(ticket_id);

    -- 3. Update the ticket state to 'used' AND update timestamp.
    -- This is only reached if the previous checks pass without raising an exception.
    UPDATE eshop.tickets
    SET
        state = 'used',
        updated_at = now()
    WHERE id = ticket_id;
END;
$$;

-- Source: database/functions/eshop_orders/update_ticket_to_unused_ws.sql
CREATE OR REPLACE FUNCTION public.update_ticket_to_unused_ws(
    ticket_id bigint
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    occasion_id bigint;
    updated_count integer;
BEGIN
    SELECT occasion
    INTO STRICT occasion_id
    FROM eshop.tickets
    WHERE id = ticket_id;

    PERFORM public.check_is_editor_order_on_occasion(occasion_id);

    IF NOT public.admit_scan_access_v1(occasion_id,true) THEN
        RAISE SQLSTATE 'PT429' USING MESSAGE='abuse_limit_exceeded';
    END IF;
    PERFORM public.check_ticket_is_mutable(ticket_id);

    UPDATE eshop.tickets
    SET
        -- `sent` is the canonical unused state that can be scanned again.
        state = 'sent',
        updated_at = now()
    WHERE id = ticket_id
      AND state = 'used';

    GET DIAGNOSTICS updated_count = ROW_COUNT;
    IF updated_count <> 1 THEN
        RAISE EXCEPTION 'Ticket % is not used.', ticket_id;
    END IF;
END;
$$;

REVOKE ALL ON FUNCTION public.update_ticket_to_unused_ws(bigint)
FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.update_ticket_to_unused_ws(bigint)
TO authenticated, service_role;


-- Source: database/functions/eshop_orders/reset_password_via_scan.sql
CREATE OR REPLACE FUNCTION public.reset_password_via_scan(
    ticket_id bigint,
    password text,
    scan_code text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    v_occasion_id bigint;
    v_expected_scan_code text;
    v_target_user_id uuid;
    v_target_email text;
    v_encrypted_pw text;
BEGIN
    IF NOT public.check_scan_attempt_budget_v1((SELECT occasion FROM eshop.tickets WHERE id=ticket_id)) THEN
        RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded');
    END IF;
    -- =================================================================
    -- 1. INPUT VALIDATION
    -- =================================================================
    IF ticket_id IS NULL THEN
         RETURN jsonb_build_object('code', 400, 'message', 'Ticket ID is missing.');
    END IF;

    IF password IS NULL OR trim(password) = '' THEN
         RETURN jsonb_build_object('code', 400, 'message', 'Password cannot be empty.');
    END IF;

    -- =================================================================
    -- 2. VALIDATE TICKET AND SCAN CODE
    -- =================================================================

    -- Get Occasion ID from Ticket
    SELECT occasion INTO v_occasion_id
    FROM eshop.tickets
    WHERE id = ticket_id;

    IF v_occasion_id IS NULL THEN
        PERFORM public.admit_scan_access_v1(NULL,false);
        RETURN jsonb_build_object('code', 404, 'message', 'Ticket not found or no occasion assigned.');
    END IF;

    -- Get Expected Scan Code (Secret) from Occasions Hidden
    SELECT oh.secret INTO v_expected_scan_code
    FROM public.occasions_hidden oh
    JOIN public.occasions o ON o.occasion_hidden = oh.id
    WHERE o.id = v_occasion_id
    LIMIT 1;

    IF v_expected_scan_code IS NULL THEN
        PERFORM public.admit_scan_access_v1(v_occasion_id,false);
        RETURN jsonb_build_object('code', 400, 'message', 'Scan code not defined for this occasion.');
    END IF;

    -- Verify Code Matches
    IF scan_code IS DISTINCT FROM v_expected_scan_code THEN
        PERFORM public.admit_scan_access_v1(v_occasion_id,false);
        RETURN jsonb_build_object('code', 401, 'message', 'Invalid scan code.');
    END IF;

    -- =================================================================
    -- 3. IDENTIFY TARGET USER
    -- =================================================================

    -- Find the user attached to this ticket via occasion_users
    SELECT "user" INTO v_target_user_id
    FROM public.occasion_users
    WHERE ticket = ticket_id;

    IF v_target_user_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'No user found associated with this ticket.');
    END IF;

    -- =================================================================
    -- 4. SECURITY CHECK: PREVENT RESET FOR PRIVILEGED USERS
    -- =================================================================
    BEGIN
        PERFORM public.check_is_scan_password_reset_target_allowed(
            v_target_user_id
        );
    EXCEPTION
        WHEN insufficient_privilege THEN
            RETURN jsonb_build_object(
                'code', 403,
                'message', 'Security Restriction: Cannot reset password for privileged users via scan.'
            );
    END;

    -- =================================================================
    -- 5. PERFORM PASSWORD RESET
    -- =================================================================

    IF NOT public.admit_scan_password_reset_v1(v_occasion_id,v_target_user_id) THEN
        RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded');
    END IF;

    -- Generate encrypted password
    v_encrypted_pw := crypt(password, gen_salt('bf'));

    -- Update auth.users
    UPDATE auth.users
    SET encrypted_password = v_encrypted_pw
    WHERE id = v_target_user_id
    RETURNING email INTO v_target_email;

    IF v_target_email IS NULL THEN
         -- Fallback if email wasn't returned (unlikely if ID exists)
         RETURN jsonb_build_object('code', 500, 'message', 'Password updated, but failed to retrieve email.');
    END IF;

    -- =================================================================
    -- 6. SUCCESS RESPONSE
    -- =================================================================
    RETURN jsonb_build_object(
        'code', 200,
        'message', 'Password successfully reset.',
        'email', v_target_email
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'code', 500,
            'message', 'An unexpected error occurred.',
            'detail', SQLERRM
        );
END;
$$;

REVOKE ALL ON FUNCTION public.reset_password_via_scan(bigint, text, text)
  FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.reset_password_via_scan(bigint, text, text)
  TO anon, authenticated, service_role;


-- Source: database/functions/abuse/qr.sql
-- Separate service RPC commits attempts before credential verification/session work.
CREATE OR REPLACE FUNCTION public.consume_qr_login_attempt_v1(p_occasion bigint DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE accepted boolean; policy jsonb; cap bigint;
BEGIN
 PERFORM public.require_service_role();
 IF p_occasion IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=p_occasion) THEN
  RETURN jsonb_build_object('allowed',false); END IF;
 policy:=public.abuse_effective_rules_v1(CASE WHEN p_occasion IS NULL THEN 'qr.global' ELSE 'qr.proof' END,NULL,NULL);
 accepted:=public.abuse_charge_v1(policy,jsonb_build_object('global','all','recipient',p_occasion::text),'{}',true);
 SELECT base_limit INTO cap FROM public.abuse_policy_rules WHERE rule_key='qr.payload.bytes';
 IF cap IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 RETURN jsonb_build_object('allowed',accepted,'maxBodyBytes',cap);
END $$;
REVOKE ALL ON FUNCTION public.consume_qr_login_attempt_v1(bigint) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.consume_qr_login_attempt_v1(bigint) TO service_role;


-- Source: database/functions/abuse/auth.sql
-- Hash the former stable SHA identity with the protected key. This permits a
-- lossless migration of already consumed budgets without storing raw IP/email.
CREATE OR REPLACE FUNCTION public.consume_auth_abuse_v1(p_family text,p_key_hash text)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.require_service_role();
 IF p_family IS NULL OR p_family NOT IN ('reset.source','reset.account','google.source','google.client','google.global','google.attempt','google.proof')
  OR p_key_hash IS NULL OR p_key_hash !~ '^[0-9a-f]{64}$' THEN RETURN false; END IF;
 RETURN public.abuse_charge_v1(public.abuse_effective_rules_v1('auth.'||p_family,NULL,NULL),
  jsonb_build_object('recipient',public.abuse_recipient_key_v1(p_key_hash),'global','all'),'{}',true);
END $$;
REVOKE ALL ON FUNCTION public.consume_auth_abuse_v1(text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.consume_auth_abuse_v1(text,text) TO service_role;

-- Compatibility signatures use the same canonical counters, never client limits.
CREATE OR REPLACE FUNCTION public.consume_password_reset_rate_limit_v1(p_key_hash text,p_limit integer,p_window_seconds integer)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR p_limit IS NULL OR p_limit NOT IN (3,20) OR p_window_seconds IS DISTINCT FROM 900 THEN RETURN false; END IF;
 RETURN public.consume_auth_abuse_v1(CASE p_limit WHEN 20 THEN 'reset.source' ELSE 'reset.account' END,p_key_hash);
END $$;
REVOKE ALL ON FUNCTION public.consume_password_reset_rate_limit_v1(text,integer,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.consume_password_reset_rate_limit_v1(text,integer,integer) TO service_role;
CREATE OR REPLACE FUNCTION public.google_auth_rate_limit_v1(p_key text,p_limit integer)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.require_service_role();
 RETURN public.consume_auth_abuse_v1(CASE p_limit WHEN 20 THEN 'google.source' WHEN 30 THEN 'google.client'
  WHEN 100 THEN 'google.global' WHEN 10 THEN 'google.attempt' WHEN 5 THEN 'google.proof' END,p_key);
END $$;
REVOKE ALL ON FUNCTION public.google_auth_rate_limit_v1(text,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.google_auth_rate_limit_v1(text,integer) TO service_role;

-- Preserve every live old window. Its class was not stored: conservatively adopt
-- it in every compatible class, with expiry bounded to the former window.
INSERT INTO public.abuse_budget_usage(rule_key,scope_id,bucket_at,amount,expires_at)
SELECT r.rule_key,public.abuse_recipient_key_v1(x.key_hash),
 to_timestamp(floor(extract(epoch FROM x.window_started_at)/r.bucket_seconds)*r.bucket_seconds),
 x.attempts,x.window_started_at+interval '20 minutes'
FROM public.password_reset_rate_limits x CROSS JOIN public.abuse_policy_rules r
WHERE r.rule_key IN ('reset.source','reset.account') AND x.window_started_at>now()-interval '15 minutes' AND x.attempts>0;
INSERT INTO public.abuse_budget_usage(rule_key,scope_id,bucket_at,amount,expires_at)
SELECT r.rule_key,public.abuse_recipient_key_v1(x.key_hash),
 to_timestamp(floor(extract(epoch FROM x.window_start)/r.bucket_seconds)*r.bucket_seconds),x.hits,x.window_start+interval '2 minutes'
FROM public.external_login_rate_limits x CROSS JOIN public.abuse_policy_rules r
WHERE r.rule_key LIKE 'google.%' AND x.window_start>now()-interval '1 minute' AND x.hits>0;
CREATE OR REPLACE FUNCTION public.cleanup_external_login_v1()
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.require_service_role();
 DELETE FROM public.external_login_attempts WHERE expires_at<clock_timestamp();
 DELETE FROM public.existing_user_session_leases WHERE expires_at<clock_timestamp();
 PERFORM public.cleanup_abuse_usage_v1();
END $$;
REVOKE ALL ON FUNCTION public.cleanup_external_login_v1() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.cleanup_external_login_v1() TO service_role;
DROP TABLE public.password_reset_rate_limits;
DROP TABLE public.external_login_rate_limits;

-- GoTrue explicitly invokes this PostgreSQL hook in its own committed transaction
-- BEFORE session issuance. This is not a database trigger. Returning reject keeps
-- consumption even when GoTrue subsequently rejects credentials or session work.
CREATE OR REPLACE FUNCTION public.password_verification_attempt_v1(event jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE actor uuid; allowed boolean;
BEGIN
 actor:=(event->>'user_id')::uuid;
 IF actor IS NULL OR jsonb_typeof(event->'valid') IS DISTINCT FROM 'boolean'
  OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=actor) THEN
  RETURN jsonb_build_object('decision','reject','message','Invalid login attempt','should_logout_user',false);
 END IF;
 allowed:=public.abuse_charge_v1(public.abuse_effective_rules_v1('auth.password',NULL,NULL),
  jsonb_build_object('actor',actor::text),'{}',true);
 RETURN jsonb_build_object('decision',CASE WHEN allowed THEN 'continue' ELSE 'reject' END,
  'message',CASE WHEN allowed THEN '' ELSE 'Too many login attempts. Try again later.' END,
  'should_logout_user',false);
END $$;
REVOKE ALL ON FUNCTION public.password_verification_attempt_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.password_verification_attempt_v1(jsonb) TO supabase_auth_admin;


-- Source: database/functions/abuse/media.sql
-- The actual IO adapter supplies the measured file size before transform/R2 put.
-- A direct call grants no storage capability and cannot refund committed IO work.
CREATE OR REPLACE FUNCTION public.admit_image_upload_v1(p_bytes bigint,p_occasion_id bigint DEFAULT NULL,p_unit_id bigint DEFAULT NULL)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE un bigint; org bigint; policy jsonb; costs jsonb;
BEGIN
 IF auth.uid() IS NULL OR (p_occasion_id IS NULL)=(p_unit_id IS NULL)
  OR public.check_upload_permission(p_occasion_id,p_unit_id) IS NOT TRUE THEN
  RAISE insufficient_privilege USING MESSAGE='image editor required'; END IF;
 IF p_bytes IS NULL OR p_bytes<=0 THEN RAISE invalid_parameter_value USING MESSAGE='image bytes required'; END IF;
 IF p_occasion_id IS NOT NULL THEN SELECT unit,organization INTO un,org FROM public.occasions WHERE id=p_occasion_id;
 ELSE SELECT id,organization INTO un,org FROM public.units WHERE id=p_unit_id; END IF;
 policy:=public.abuse_effective_rules_v1('image.upload',un,org);
 costs:=jsonb_build_object('image.upload.actor.bytes',p_bytes,'image.upload.unit.bytes',p_bytes,'image.upload.organization.bytes',p_bytes);
 PERFORM public.abuse_charge_v1(policy,jsonb_build_object('actor',auth.uid(),'unit',un,'organization',org),costs);
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.admit_image_upload_v1(bigint,bigint,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admit_image_upload_v1(bigint,bigint,bigint) TO authenticated;

CREATE OR REPLACE FUNCTION public.admit_external_image_fetch_v1(p_occasion_id bigint DEFAULT NULL,p_unit_id bigint DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE un bigint; org bigint; policy jsonb; cap bigint;
BEGIN
 IF auth.uid() IS NULL OR (p_occasion_id IS NULL)=(p_unit_id IS NULL)
  OR public.check_upload_permission(p_occasion_id,p_unit_id) IS NOT TRUE THEN
  RAISE insufficient_privilege USING MESSAGE='image editor required'; END IF;
 IF p_occasion_id IS NOT NULL THEN SELECT unit,organization INTO un,org FROM public.occasions WHERE id=p_occasion_id;
 ELSE SELECT id,organization INTO un,org FROM public.units WHERE id=p_unit_id; END IF;
 policy:=public.abuse_effective_rules_v1('image.fetch',un,org);
 SELECT (r->>'base_limit')::bigint INTO cap FROM jsonb_array_elements(policy->'rules') r WHERE r->>'rule_key'='image.fetch.payload.bytes';
 IF cap IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 PERFORM public.abuse_charge_v1(policy,jsonb_build_object('actor',auth.uid(),'unit',un,'organization',org),jsonb_build_object('image.fetch.payload.bytes',cap));
 RETURN jsonb_build_object('allowed',true,'maxBytes',cap);
END $$;
REVOKE ALL ON FUNCTION public.admit_external_image_fetch_v1(bigint,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admit_external_image_fetch_v1(bigint,bigint) TO authenticated;

-- Called with actual transformed output bytes by the existing R2 IO adapter.
-- A direct RPC cannot write to R2 or refund any committed allocation.
CREATE OR REPLACE FUNCTION public.admit_image_storage_v1(p_bytes bigint,p_occasion_id bigint DEFAULT NULL,p_unit_id bigint DEFAULT NULL)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE un bigint; org bigint;
BEGIN
 IF auth.uid() IS NULL OR (p_occasion_id IS NULL)=(p_unit_id IS NULL)
  OR public.check_upload_permission(p_occasion_id,p_unit_id) IS NOT TRUE THEN
  RAISE insufficient_privilege USING MESSAGE='image editor required'; END IF;
 IF p_bytes IS NULL OR p_bytes<=0 THEN RAISE invalid_parameter_value USING MESSAGE='actual storage bytes required'; END IF;
 IF p_occasion_id IS NOT NULL THEN SELECT unit,organization INTO un,org FROM public.occasions WHERE id=p_occasion_id;
 ELSE SELECT id,organization INTO un,org FROM public.units WHERE id=p_unit_id; END IF;
 PERFORM public.abuse_charge_v1(public.abuse_effective_rules_v1('image.storage',un,org),
  jsonb_build_object('unit',un,'organization',org,'global','all'),
  jsonb_build_object('image.storage.unit.bytes',p_bytes,'image.storage.organization.bytes',p_bytes,'image.storage.global.bytes',p_bytes));
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.admit_image_storage_v1(bigint,bigint,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admit_image_storage_v1(bigint,bigint,bigint) TO authenticated;


-- Source: database/functions/abuse/documents.sql
-- Fixed output/asset limits accompany the existing admitted document response.
CREATE OR REPLACE FUNCTION public.bound_document_data_v1(data jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE policy jsonb; limits jsonb; cap bigint;
BEGIN
 policy:=public.abuse_effective_rules_v1('document.output',NULL,NULL);
 IF policy IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 SELECT jsonb_object_agg(r->>'rule_key',(r->>'base_limit')::bigint) INTO limits FROM jsonb_array_elements(policy->'rules') r;
 cap:=(limits->>'document.input.bytes')::bigint;
 IF octet_length(data::text)>cap THEN RAISE SQLSTATE 'PT429' USING MESSAGE='document_input_limit'; END IF;
 RETURN data||jsonb_build_object('abuseLimits',limits);
END $$;
REVOKE ALL ON FUNCTION public.bound_document_data_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.admit_ticket_document_internal_v1(p_occasion bigint)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE o public.occasions; policy jsonb;
BEGIN
 SELECT * INTO STRICT o FROM public.occasions WHERE id=p_occasion;
 policy:=public.abuse_effective_rules_v1('ticket.document',o.unit,o.organization);
 IF auth.uid() IS NULL THEN
  policy:=jsonb_set(policy,'{rules}',(SELECT jsonb_agg(value) FROM jsonb_array_elements(policy->'rules') WHERE value->>'scope_kind'<>'actor'));
 END IF;
 PERFORM public.abuse_charge_v1(policy,jsonb_build_object('actor',auth.uid(),'unit',o.unit,'organization',o.organization));
END $$;
REVOKE ALL ON FUNCTION public.admit_ticket_document_internal_v1(bigint) FROM PUBLIC,anon,authenticated,service_role;

-- Authorization, resource selection and admission happen before the existing
-- expensive read. The transport never supplies an actor, Unit or Organization.
CREATE OR REPLACE FUNCTION public.get_ticket_document_data_v1(p_ticket bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE occ bigint;
BEGIN
 SELECT occasion INTO occ FROM eshop.tickets WHERE id=p_ticket;
 IF occ IS NULL OR NOT (public.is_service_role() OR (auth.uid() IS NOT NULL AND public.get_is_editor_order_view_on_occasion(occ))) THEN
  RAISE insufficient_privilege USING MESSAGE='ticket document access denied'; END IF;
 PERFORM public.admit_ticket_document_internal_v1(occ);
 RETURN public.bound_document_data_v1(public.get_ticket_details_for_generating(p_ticket));
END $$;
