-- Source: database/functions/abuse/storage.sql
-- Canonical image writes belong to the existing R2 control Worker. A released
-- client's Storage copy/upload must not become an unmetered alternate writer.
-- Restrictive policies compose with existing read/delete permissions and do
-- not affect service-owned ticket fonts or other unrelated buckets.
DROP POLICY IF EXISTS image_storage_write_cutover_insert ON storage.objects;
CREATE POLICY image_storage_write_cutover_insert ON storage.objects AS RESTRICTIVE
 FOR INSERT TO anon,authenticated
 WITH CHECK (bucket_id NOT IN ('public-files','images-temp','editor-files'));
DROP POLICY IF EXISTS image_storage_write_cutover_update ON storage.objects;
CREATE POLICY image_storage_write_cutover_update ON storage.objects AS RESTRICTIVE
 FOR UPDATE TO anon,authenticated
 USING (bucket_id NOT IN ('public-files','images-temp','editor-files'))
 WITH CHECK (bucket_id NOT IN ('public-files','images-temp','editor-files'));

-- A historical name is only an exact lookup key, never ownership evidence.
-- Every corresponding canonical image link must pass the existing complete-
-- batch authorization; adding a second owned row cannot steal another owner.
CREATE INDEX IF NOT EXISTS images_link_abuse ON public.images(link);
CREATE OR REPLACE FUNCTION public.can_delete_legacy_image_v1(p_name text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE links text[];
BEGIN
 IF auth.uid() IS NULL OR p_name IS NULL THEN RETURN false; END IF;
 SELECT array_agg(DISTINCT link) INTO links FROM public.images
 WHERE link='https://api.festapp.net/storage/v1/object/public/public-files/'||p_name;
 IF links IS NULL THEN RETURN false; END IF;
 PERFORM 1 FROM public.authorize_image_deletion(links);
 RETURN true;
EXCEPTION WHEN insufficient_privilege OR invalid_parameter_value THEN RETURN false;
END $$;
REVOKE ALL ON FUNCTION public.can_delete_legacy_image_v1(text) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.can_delete_legacy_image_v1(text) TO authenticated;
DROP POLICY IF EXISTS "Public Images Policy" ON storage.objects;
DROP POLICY IF EXISTS image_storage_legacy_select ON storage.objects;
CREATE POLICY image_storage_legacy_select ON storage.objects FOR SELECT TO authenticated
 USING (bucket_id='public-files' AND public.can_delete_legacy_image_v1(name));
DROP POLICY IF EXISTS image_storage_legacy_delete ON storage.objects;
CREATE POLICY image_storage_legacy_delete ON storage.objects FOR DELETE TO authenticated
 USING (bucket_id='public-files' AND public.can_delete_legacy_image_v1(name));
DROP POLICY IF EXISTS image_storage_listing_owner ON storage.objects;
CREATE POLICY image_storage_listing_owner ON storage.objects AS RESTRICTIVE FOR SELECT TO authenticated
 USING (bucket_id<>'public-files' OR public.can_delete_legacy_image_v1(name));
DROP POLICY IF EXISTS image_storage_no_anonymous_listing ON storage.objects;
CREATE POLICY image_storage_no_anonymous_listing ON storage.objects AS RESTRICTIVE FOR SELECT TO anon
 USING (bucket_id<>'public-files');
DROP POLICY IF EXISTS image_storage_delete_owner ON storage.objects;
CREATE POLICY image_storage_delete_owner ON storage.objects AS RESTRICTIVE
 FOR DELETE TO authenticated
 USING (bucket_id<>'public-files' OR public.can_delete_legacy_image_v1(name));

CREATE INDEX IF NOT EXISTS images_occasion_abuse ON public.images(occasion) WHERE occasion IS NOT NULL;
CREATE INDEX IF NOT EXISTS images_unit_abuse ON public.images(unit) WHERE unit IS NOT NULL;
CREATE OR REPLACE FUNCTION public.admit_image_record_v1(p_link text,p_occasion bigint,p_unit bigint) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE un bigint; org bigint; policy jsonb; scopes jsonb; r jsonb; unit_count bigint; org_count bigint;
BEGIN
 IF auth.uid() IS NULL OR (p_occasion IS NULL)=(p_unit IS NULL) OR public.check_upload_permission(p_occasion,p_unit) IS NOT TRUE THEN
  RAISE insufficient_privilege USING MESSAGE='exactly one authorized image owner required'; END IF;
 IF p_link IS NULL OR p_link !~ '^https://(a\.)?img\.festapp\.net/images/[A-Za-z0-9_./-]+$' THEN
  RAISE invalid_parameter_value USING MESSAGE='canonical public image URL required'; END IF;
 IF p_occasion IS NOT NULL THEN SELECT unit,organization INTO un,org FROM public.occasions WHERE id=p_occasion;
 ELSE SELECT id,organization INTO un,org FROM public.units WHERE id=p_unit; END IF;
 policy:=public.abuse_effective_rules_v1('image.records',un,org);
 scopes:=jsonb_build_object('actor',auth.uid(),'unit',un,'organization',org);
 FOR r IN SELECT value FROM jsonb_array_elements(policy->'rules') ORDER BY value->>'rule_key' LOOP
  IF r->>'kind' IN ('rolling','occupancy') THEN
   PERFORM pg_advisory_xact_lock(hashtextextended('abuse:'||(r->>'rule_key')||':'||(scopes->>(r->>'scope_kind')),0));
  END IF;
 END LOOP;
 SELECT count(*) FILTER(WHERE coalesce(i.unit,o.unit)=un),count(*) INTO unit_count,org_count
 FROM public.images i LEFT JOIN public.occasions o ON o.id=i.occasion LEFT JOIN public.units u ON u.id=i.unit
 WHERE coalesce(o.organization,u.organization)=org;
 PERFORM public.abuse_charge_v1(policy,scopes,jsonb_build_object('image.records.link.bytes',octet_length(p_link),
  'image.records.stored.unit',unit_count+1,'image.records.stored.organization',org_count+1));
END $$;
REVOKE ALL ON FUNCTION public.admit_image_record_v1(text,bigint,bigint) FROM PUBLIC,anon,authenticated,service_role;
REVOKE INSERT,UPDATE ON public.images FROM PUBLIC,anon,authenticated;


-- Source: database/functions/others/add_image_record.sql
CREATE OR REPLACE FUNCTION public.add_image_record(p_link text, p_occasion_id bigint, p_unit_id bigint)
RETURNS void
SECURITY DEFINER
LANGUAGE plpgsql
SET search_path = public, extensions
AS $$
DECLARE v_image_id bigint;
BEGIN
    -- Permission Check
    IF p_unit_id IS NOT NULL THEN
        -- Unit Editor
        IF (SELECT public.get_is_editor_on_unit(p_unit_id)) IS NOT TRUE THEN
            RAISE EXCEPTION 'Permission denied: User is not an editor of this unit.';
        END IF;
    ELSIF p_occasion_id IS NOT NULL THEN
        -- Occasion Editor OR Occasion Order Editor
        IF (public.get_is_editor_on_occasion(p_occasion_id)) IS NOT TRUE 
           AND (public.get_is_editor_order_on_occasion(p_occasion_id)) IS NOT TRUE THEN
             RAISE EXCEPTION 'Permission denied: User is not an editor/order-editor of this occasion.';
        END IF;
    ELSE
        RAISE EXCEPTION 'Entity ID (unit or occasion) must be provided.';
    END IF;

    -- Insert Record
    PERFORM public.admit_image_record_v1(p_link,p_occasion_id,p_unit_id);
    INSERT INTO public.images (link, occasion, unit)
    VALUES (p_link, p_occasion_id, p_unit_id)
    RETURNING id INTO v_image_id;

    IF p_occasion_id IS NOT NULL THEN
      PERFORM public.record_client_sync_commit_v1(
        p_occasion_id,'image.add','content',jsonb_build_array(jsonb_build_object(
          'entityType','occasion_image','entityId',v_image_id::text,
          'operation','insert','safeLabel',left(p_link,240),
          'changedFields',jsonb_build_array('link'))),
        ARRAY['occasion_config'],'[]'::jsonb,'[]'::jsonb,'user',NULL);
    END IF;
END;
$$;


-- Source: database/functions/abuse/health.sql
-- Read-only operator evidence. Labels are the three fixed mail classes, never
-- recipient/source/UUID. The endpoint does no cleanup, dispatch or provider IO.
CREATE INDEX email_pending_class_age ON public.email_messages(admission_class,created_at)
 WHERE workflow_state IN ('pending','blocked','preparing','sending','retry_wait','unknown');
CREATE INDEX abuse_evidence_age ON public.abuse_unit_evidence(measured_at);

CREATE OR REPLACE FUNCTION public.abuse_health_internal_v1() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE queues jsonb; expired_at timestamptz; evidence_at timestamptz; capacity jsonb;
BEGIN
 SELECT jsonb_object_agg(class,stats) INTO queues FROM (
  SELECT class,jsonb_build_object(
   'pendingCount',least(5000,(SELECT count(*) FROM (
     SELECT 1 FROM public.email_messages WHERE admission_class=class
      AND workflow_state IN ('pending','blocked','preparing','sending','retry_wait','unknown') LIMIT 5001
    ) q)),
   'countCappedAt',5000,
   'oldestCreatedAt',(SELECT created_at FROM public.email_messages WHERE admission_class=class
     AND workflow_state IN ('pending','blocked','preparing','sending','retry_wait','unknown') ORDER BY created_at LIMIT 1)
  ) stats FROM unnest(ARRAY['ordinary','auth','commitment']) class
 ) q;
 SELECT expires_at INTO expired_at FROM public.abuse_budget_usage WHERE expires_at<statement_timestamp() ORDER BY expires_at LIMIT 1;
 SELECT measured_at INTO evidence_at FROM public.abuse_unit_evidence ORDER BY measured_at LIMIT 1;
 SELECT jsonb_build_object('paused',paused,'quotaMeasuredAt',quota_at,'circuitUntil',circuit_until,
   'nextSendAt',next_send_at,'providerOutageStreak',provider_outage_streak) INTO capacity FROM public.email_capacity LIMIT 1;
 RETURN jsonb_build_object('measuredAt',statement_timestamp(),
  'policyRevision',(SELECT revision FROM public.abuse_policy_revision WHERE singleton),
  'queue',queues,'oldestExpiredUsageAt',expired_at,'oldestGrowthEvidenceAt',evidence_at,'provider',capacity);
END $$;
REVOKE ALL ON FUNCTION public.abuse_health_internal_v1() FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.get_abuse_health_v1() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.require_service_role();
 RETURN public.abuse_health_internal_v1();
END $$;
REVOKE ALL ON FUNCTION public.get_abuse_health_v1() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_abuse_health_v1() TO service_role;

-- A dedicated random monitoring capability has no table, write or service-role
-- authority. Only its SHA-256 digest is persisted, provisioned at activation.
CREATE TABLE public.abuse_monitor_key(singleton boolean PRIMARY KEY CHECK(singleton),token_hash bytea CHECK(octet_length(token_hash)=32));
INSERT INTO public.abuse_monitor_key VALUES(true,NULL);
ALTER TABLE public.abuse_monitor_key ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.abuse_monitor_key FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.get_abuse_monitor_v1(p_token text) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE expected bytea; state jsonb; alarm_policy jsonb;
BEGIN
 IF p_token IS NULL OR p_token !~ '^[0-9a-f]{64}$' THEN RAISE insufficient_privilege USING MESSAGE='monitor denied'; END IF;
 SELECT token_hash INTO expected FROM public.abuse_monitor_key WHERE singleton;
 IF expected IS NULL OR extensions.digest(p_token,'sha256') IS DISTINCT FROM expected THEN
  RAISE insufficient_privilege USING MESSAGE='monitor denied'; END IF;
 state:=public.abuse_health_internal_v1();
 alarm_policy:=public.abuse_effective_rules_v1('monitor.thresholds',NULL,NULL);
 IF alarm_policy IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 RETURN state||jsonb_build_object('thresholds',(SELECT jsonb_object_agg(r->>'rule_key',(r->>'base_limit')::bigint) FROM jsonb_array_elements(alarm_policy->'rules') r));
END $$;
REVOKE ALL ON FUNCTION public.get_abuse_monitor_v1(text) FROM PUBLIC,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.get_abuse_monitor_v1(text) TO anon;


